INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_a917ef73842439', 'subj_math', 'slope-intercept-form', 'Slope-intercept form', 'y = mx + b', 'Equation of a non-vertical line with slope m that crosses the y-axis at (0, b).', '[{"symbol":"m","meaning":"slope"},{"symbol":"b","meaning":"y-intercept"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_619ad09fad8869', 'subj_math', 'point-slope-form', 'Point-slope form', 'y - y_1 = m(x - x_1)', 'Equation of the line with slope m through the point (x₁, y₁).', '[{"symbol":"m","meaning":"slope"},{"symbol":"(x_1, y_1)","meaning":"a point on the line"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_92aecf8b558a5d', 'subj_math', 'vertex-form', 'Vertex form of a quadratic', 'y = a(x - h)^2 + k', 'A parabola with vertex (h, k). It opens up when a > 0 and down when a < 0; |a| sets how narrow it is.', '[{"symbol":"a","meaning":"vertical stretch factor, a ≠ 0"},{"symbol":"(h, k)","meaning":"vertex"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_3a01f099257681', 'subj_math', 'discriminant', 'Discriminant', '\Delta = b^2 - 4ac', 'For ax² + bx + c = 0 with real coefficients: Δ > 0 gives two real solutions, Δ = 0 one repeated real solution, Δ < 0 two complex solutions.', '[{"symbol":"a, b, c","meaning":"coefficients, a ≠ 0"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_1ec6e1d32d8ff2', 'subj_math', 'distance-formula', 'Distance formula', 'd = \sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}', 'Distance between two points in the coordinate plane; it is the Pythagorean theorem applied to the horizontal and vertical changes.', '[{"symbol":"(x_1, y_1), (x_2, y_2)","meaning":"the two points"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_5cbc7fb7e3ffab', 'subj_math', 'pythagorean-identity', 'Pythagorean identity', '\sin^2\theta + \cos^2\theta = 1', 'True for every angle θ; it follows from the unit circle x² + y² = 1.', '[{"symbol":"\\theta","meaning":"any angle"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_7e40b2ca0e18e3', 'subj_math', 'z-score', 'z-score', 'z = \frac{x - \mu}{\sigma}', 'How many standard deviations a value x lies above (positive) or below (negative) the mean.', '[{"symbol":"x","meaning":"observed value"},{"symbol":"\\mu","meaning":"mean"},{"symbol":"\\sigma","meaning":"standard deviation, σ > 0"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_b85060863d3c28', 'subj_math', 'derivative-definition', 'Definition of the derivative', 'f''(a) = \lim_{h \to 0} \frac{f(a + h) - f(a)}{h}', 'The instantaneous rate of change of f at x = a, when this limit exists.', '[{"symbol":"f''(a)","meaning":"derivative of f at a"},{"symbol":"h","meaning":"a small change in x"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_af5c992f056f3a', 'subj_math', 'power-rule', 'Power rule', '\frac{d}{dx}\,x^n = n x^{n-1}', 'Derivative of a power function. Holds for every real exponent n where x^n is differentiable.', '[{"symbol":"n","meaning":"a real constant"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_9a936b74437366', 'subj_math', 'riemann-sum', 'Riemann sum', '\sum_{i=1}^{n} f(x_i^*)\,\Delta x, \quad \Delta x = \frac{b - a}{n}', 'Approximates the definite integral of f on [a, b] with n equal-width rectangles; x_i* is a sample point in the i-th subinterval.', '[{"symbol":"n","meaning":"number of subintervals"},{"symbol":"\\Delta x","meaning":"width of each subinterval"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_b8349176e9e8d1', 'subj_math', 'ftc', 'Fundamental Theorem of Calculus', '\int_a^b f(x)\,dx = F(b) - F(a)', 'If f is continuous on [a, b] and F is any antiderivative of f, the definite integral equals F(b) − F(a).', '[{"symbol":"F","meaning":"an antiderivative of f (F′ = f)"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_9a8aa464cf15cf', 'subj_phys', 'displacement-constant-acceleration', 'Displacement under constant acceleration', '\Delta x = v_0 t + \tfrac{1}{2} a t^2', 'One-dimensional motion with constant acceleration.', '[{"symbol":"\\Delta x","meaning":"displacement","unit":"m"},{"symbol":"v_0","meaning":"initial velocity","unit":"m/s"},{"symbol":"a","meaning":"acceleration","unit":"m/s²"},{"symbol":"t","meaning":"time","unit":"s"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_085a19ad8dbfb2', 'subj_phys', 'projectile-range', 'Range of a projectile (level ground)', 'R = \frac{v_0^2 \sin 2\theta}{g}', 'Horizontal distance for a launch and landing at the same height, ignoring air resistance.', '[{"symbol":"v_0","meaning":"launch speed","unit":"m/s"},{"symbol":"\\theta","meaning":"launch angle above horizontal"},{"symbol":"g","meaning":"gravitational acceleration","unit":"m/s²"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_fdf0e0559e8bec', 'subj_phys', 'kinetic-friction', 'Kinetic friction', 'f_k = \mu_k F_N', 'Magnitude of the friction force on a sliding object; it points opposite the motion relative to the surface.', '[{"symbol":"\\mu_k","meaning":"coefficient of kinetic friction"},{"symbol":"F_N","meaning":"normal force","unit":"N"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_13b3934d503dc0', 'subj_phys', 'hookes-law', 'Hooke''s law', 'F_s = -kx', 'Force of an ideal spring stretched or compressed by x from equilibrium; the minus sign means it points back toward equilibrium.', '[{"symbol":"k","meaning":"spring constant","unit":"N/m"},{"symbol":"x","meaning":"displacement from equilibrium","unit":"m"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_6dd466c48d8baf', 'subj_phys', 'spring-period', 'Period of a mass on a spring', 'T = 2\pi\sqrt{\frac{m}{k}}', 'Period of an ideal mass-spring oscillator. It does not depend on amplitude.', '[{"symbol":"T","meaning":"period","unit":"s"},{"symbol":"m","meaning":"mass","unit":"kg"},{"symbol":"k","meaning":"spring constant","unit":"N/m"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_66bdfe1d6261ba', 'subj_phys', 'ohms-law', 'Ohm''s law', 'V = IR', 'Relates voltage across a resistor to the current through it, for ohmic materials at constant temperature.', '[{"symbol":"V","meaning":"potential difference","unit":"V"},{"symbol":"I","meaning":"current","unit":"A"},{"symbol":"R","meaning":"resistance","unit":"Ω"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_e06793f7601e9a', 'subj_phys', 'resistors-series-parallel', 'Equivalent resistance', 'R_s = R_1 + R_2 + \cdots, \qquad \frac{1}{R_p} = \frac{1}{R_1} + \frac{1}{R_2} + \cdots', 'Series resistors add; for parallel resistors the reciprocals add.', '[{"symbol":"R_s, R_p","meaning":"series and parallel equivalents","unit":"Ω"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_17cac0e5546069', 'subj_phys', 'electric-power', 'Electric power', 'P = IV = I^2 R = \frac{V^2}{R}', 'Rate at which a circuit element transfers energy. The forms with R apply to resistors.', '[{"symbol":"P","meaning":"power","unit":"W"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_d8fec2df8d1c29', 'subj_phys', 'kinetic-energy', 'Kinetic energy', 'K = \tfrac{1}{2} m v^2', 'Energy of an object due to its motion (translational).', '[{"symbol":"m","meaning":"mass","unit":"kg"},{"symbol":"v","meaning":"speed","unit":"m/s"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_11d17c288dc2ab', 'subj_phys', 'spring-potential-energy', 'Elastic potential energy', 'U_s = \tfrac{1}{2} k x^2', 'Energy stored in an ideal spring stretched or compressed by x.', '[{"symbol":"k","meaning":"spring constant","unit":"N/m"},{"symbol":"x","meaning":"displacement from equilibrium","unit":"m"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_26fb97b1322f8a', 'subj_chem', 'molar-mass-moles', 'Moles from mass', 'n = \frac{m}{M}', 'Converts a sample''s mass to amount in moles.', '[{"symbol":"n","meaning":"amount","unit":"mol"},{"symbol":"m","meaning":"mass","unit":"g"},{"symbol":"M","meaning":"molar mass","unit":"g/mol"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_1d94434482a72e', 'subj_chem', 'percent-yield', 'Percent yield', '\text{percent yield} = \frac{\text{actual yield}}{\text{theoretical yield}} \times 100\%', 'Compares the product actually obtained with the maximum predicted by stoichiometry.', '[]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_7ec3ff589cbd40', 'subj_chem', 'combined-gas-law', 'Combined gas law', '\frac{P_1 V_1}{T_1} = \frac{P_2 V_2}{T_2}', 'For a fixed amount of an ideal gas. Temperatures must be absolute (kelvin).', '[{"symbol":"P","meaning":"pressure"},{"symbol":"V","meaning":"volume"},{"symbol":"T","meaning":"absolute temperature","unit":"K"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_71a061244394ec', 'subj_chem', 'celsius-to-kelvin', 'Celsius to kelvin', 'T_{\text{K}} = T_{^\circ\text{C}} + 273.15', 'Gas-law calculations require absolute temperature.', '[]', 'published');

-- Lesson: equations-variables-both-sides
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_55625c238d6c30', 'equations-variables-both-sides', 'Equations with variables on both sides', 'Collect variable terms on one side, then solve; recognize equations with no solution or infinitely many solutions.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3f73e8e61bab01', 'les_55625c238d6c30', 1, 'Solve linear equations that have the variable on both sides.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_87d168f3f1c8cd', 'les_55625c238d6c30', 2, 'Use the distributive property and combine like terms before solving.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_be0540cf024f5e', 'les_55625c238d6c30', 3, 'Identify equations that have no solution or infinitely many solutions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3f73e8e61bab01', 'les_55625c238d6c30', 'learn', 1, 'text', '{"body":"When the variable appears on both sides, as in $5x - 4 = 2x + 11$, the first goal is to gather all the variable terms on one side. Subtracting $2x$ from both sides keeps the equation balanced and leaves a two-step equation you already know how to solve."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87d168f3f1c8cd', 'les_55625c238d6c30', 'learn', 2, 'worked_example', '{"title":"Solve $5x - 4 = 2x + 11$","steps":[{"latex":"5x - 2x - 4 = 2x - 2x + 11","explanation":"Subtract $2x$ from both sides."},{"latex":"3x - 4 = 11","explanation":"Combine like terms."},{"latex":"3x = 15","explanation":"Add 4 to both sides."},{"latex":"x = 5","explanation":"Divide both sides by 3."}],"check":"Left: $5(5) - 4 = 21$. Right: $2(5) + 11 = 21$. Both sides match."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be0540cf024f5e', 'les_55625c238d6c30', 'learn', 3, 'callout', '{"tone":"tip","title":"Which side should the variable go to?","body":"Either works. Moving the smaller coefficient avoids negative coefficients: in $2x + 9 = 7x - 1$, subtracting $2x$ gives $9 = 5x - 1$, so $x = 2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b8679a36368d9b', 'les_55625c238d6c30', 'learn', 4, 'worked_example', '{"title":"Solve $3(2x - 1) = 4x + 9$","steps":[{"latex":"6x - 3 = 4x + 9","explanation":"Distribute the 3 to both terms in parentheses."},{"latex":"2x - 3 = 9","explanation":"Subtract $4x$ from both sides."},{"latex":"2x = 12","explanation":"Add 3."},{"latex":"x = 6","explanation":"Divide by 2."}],"check":"Left: $3(11) = 33$. Right: $24 + 9 = 33$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d6325dbeacff60', 'les_55625c238d6c30', 'learn', 5, 'definition', '{"term":"Identity","body":"An equation that is true for every value of the variable, such as $2(x + 3) = 2x + 6$. Simplifying leads to a true statement like $6 = 6$, so there are infinitely many solutions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e925ddf79198e5', 'les_55625c238d6c30', 'learn', 6, 'definition', '{"term":"Contradiction","body":"An equation that is never true, such as $x + 4 = x + 7$. Simplifying leads to a false statement like $4 = 7$, so there is no solution."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fed2c21f90239a', 'les_55625c238d6c30', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Plan A costs 40 dollars plus 5 dollars per class; plan B costs 10 dollars per class. Setting $40 + 5c = 10c$ gives $c = 8$: at 8 classes the plans cost the same, and beyond that plan A is cheaper."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3f73e8e61bab01', 'les_55625c238d6c30', 1, 'practice', 'numeric', 1, 'Solve $7x + 2 = 3x + 18$.', '{"answer":4}', '["Subtract $3x$ from both sides."]', '$4x + 2 = 18$, $4x = 16$, $x = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87d168f3f1c8cd', 'les_55625c238d6c30', 2, 'practice', 'numeric', 2, 'Solve $4(x - 3) = 2x + 6$.', '{"answer":9}', '["Distribute first: 4x − 12."]', '$4x - 12 = 2x + 6$, $2x = 18$, $x = 9$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_be0540cf024f5e', 'les_55625c238d6c30', 3, 'practice', 'numeric', 2, 'Solve $2x + 9 = 7x - 1$.', '{"answer":2}', '["Subtract $2x$ to keep the coefficient positive."]', '$9 = 5x - 1$, $10 = 5x$, $x = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b8679a36368d9b', 'les_55625c238d6c30', 4, 'practice', 'multiple_choice', 2, 'How many solutions does $3(x + 2) = 3x + 6$ have?', '{"choices":["None","Exactly one","Exactly two","Infinitely many"],"answer":3}', '["Distribute the left side and compare."]', '$3x + 6 = 3x + 6$ is true for every $x$, so it is an identity with infinitely many solutions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d6325dbeacff60', 'les_55625c238d6c30', 5, 'practice', 'multiple_choice', 2, 'How many solutions does $5x - 1 = 5x + 4$ have?', '{"choices":["None","Exactly one","Infinitely many","It depends on x"],"answer":0}', '["Subtract $5x$ from both sides."]', 'You get $-1 = 4$, which is false, so there is no solution.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e925ddf79198e5', 'les_55625c238d6c30', 6, 'review', 'numeric', 3, 'Two phone plans: A costs 20 dollars plus 0.10 dollars per minute; B costs 0.25 dollars per minute. For how many minutes do they cost the same?', '{"answer":133.33,"tolerance":0.01}', '["Set $20 + 0.10m = 0.25m$."]', '$20 = 0.15m$, so $m = \frac{20}{0.15} \approx 133.33$ minutes.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ee5389d7c2c9ca', 'subj_math', 'solving-linear-equations', 'Solving linear equations', 'Using inverse operations and the properties of equality to find the value of an unknown.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_55625c238d6c30', (SELECT id FROM concepts WHERE slug = 'solving-linear-equations'));

-- Lesson: function-transformations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d25fe88520a9bc', 'function-transformations', 'Transformations of functions', 'Shift, reflect and stretch graphs by changing a function''s formula, and predict the new graph from the change.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c10021c49d231a', 'les_d25fe88520a9bc', 1, 'Describe how f(x) + k, f(x − h), a·f(x) and f(bx) change the graph of f.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_653da580260c01', 'les_d25fe88520a9bc', 2, 'Write the formula of a transformed function from a description or graph.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0664b00bc5c5b9', 'les_d25fe88520a9bc', 3, 'Track key points through a sequence of transformations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c10021c49d231a', 'les_d25fe88520a9bc', 'learn', 1, 'text', '{"body":"Transformations let you graph a whole family of functions by understanding one parent function well. If you know $f(x) = x^2$, you can sketch $2(x - 3)^2 + 1$ without plotting a table."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_653da580260c01', 'les_d25fe88520a9bc', 'learn', 2, 'formula', '{"latex":"g(x) = a\\,f\\big(b(x - h)\\big) + k","title":"General transformation","note":"$h$ shifts horizontally, $k$ shifts vertically, $a$ stretches or reflects vertically, $b$ stretches or reflects horizontally."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0664b00bc5c5b9', 'les_d25fe88520a9bc', 'learn', 3, 'text', '{"body":"Changes outside the function act on outputs ($y$-values) and behave the way they look: $f(x) + 3$ moves the graph up 3, and $2f(x)$ doubles every $y$-value. Changes inside act on inputs and behave in reverse: $f(x - 3)$ moves the graph right 3, and $f(2x)$ squeezes it horizontally by a factor of $\\tfrac{1}{2}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c6da45361e3bdb', 'les_d25fe88520a9bc', 'learn', 4, 'callout', '{"tone":"tip","title":"Why inside changes run backwards","body":"For $g(x) = f(x - 3)$, the output $g(5)$ equals $f(2)$. To get the same output $f$ gave at 2, $g$ needs an input 3 larger, so every point moves 3 to the right."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96decbbb3f82f5', 'les_d25fe88520a9bc', 'learn', 5, 'worked_example', '{"title":"Describe $g(x) = -\\tfrac{1}{2}|x + 4| - 1$ relative to $f(x) = |x|$","steps":[{"latex":"a = -\\tfrac{1}{2},\\ h = -4,\\ k = -1","explanation":"Match to $a f(x - h) + k$; note $x + 4 = x - (-4)$."},{"latex":"\\text{reflect, compress by } \\tfrac{1}{2}","explanation":"a < 0 reflects across the x-axis; |a| < 1 compresses vertically."},{"latex":"\\text{left } 4,\\ \\text{down } 1","explanation":"The vertex moves from (0, 0) to (−4, −1)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_854b5523c03b9d', 'les_d25fe88520a9bc', 'learn', 6, 'worked_example', '{"title":"Track the point $(2, 4)$ on $y = x^2$ under $y = 3(x + 1)^2 - 5$","steps":[{"latex":"(2, 4) \\to (1, 4)","explanation":"x + 1 inside: shift left 1."},{"latex":"(1, 4) \\to (1, 12)","explanation":"Multiply the y-value by 3."},{"latex":"(1, 12) \\to (1, 7)","explanation":"Subtract 5."}],"check":"Check: $3(1 + 1)^2 - 5 = 12 - 5 = 7$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb774d80c1820c', 'les_d25fe88520a9bc', 'learn', 7, 'callout', '{"tone":"warning","title":"Order matters for y-values","body":"Apply the stretch before the vertical shift: in $3f(x) - 5$, multiply by 3 first, then subtract 5. Doing it the other way gives the wrong point."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4ba1d9ef6bf60b', 'les_d25fe88520a9bc', 'experiment', 8, 'activity', '{"activity":"vertex-explorer","title":"Transform y = x²"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_53270debd0e68c', 'les_d25fe88520a9bc', 'experiment', 9, 'callout', '{"tone":"tip","title":"Investigate","body":"Make the graph of $y = x^2$ shifted left 3 and reflected. Then drag the gold point to make it twice as steep. Write the formula before checking the readout."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c10021c49d231a', 'les_d25fe88520a9bc', 1, 'practice', 'multiple_choice', 1, 'How is the graph of $y = f(x - 5)$ related to $y = f(x)$?', '{"choices":["Up 5","Down 5","Right 5","Left 5"],"answer":2}', '["Inside changes act on x, in reverse."]', 'Subtracting 5 inside shifts the graph 5 units right.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_653da580260c01', 'les_d25fe88520a9bc', 2, 'practice', 'multiple_choice', 1, 'Which describes $y = -f(x)$?', '{"choices":["Reflection across the x-axis","Reflection across the y-axis","Shift down 1","Horizontal stretch"],"answer":0}', '["The negative is outside, applied to outputs."]', 'Every y-value changes sign, which reflects the graph across the x-axis.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0664b00bc5c5b9', 'les_d25fe88520a9bc', 3, 'practice', 'short_text', 2, 'Write $g(x)$ for the graph of $f(x) = x^2$ shifted left 2 and up 7. Use the form g(x)=(x+?)^2+?', '{"accept":["g(x)=(x+2)^2+7","(x+2)^2+7","y=(x+2)^2+7"]}', '["Left 2 means replace x with x + 2."]', '$g(x) = (x + 2)^2 + 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c6da45361e3bdb', 'les_d25fe88520a9bc', 4, 'practice', 'short_text', 2, 'The point $(3, 9)$ is on $y = x^2$. What point is on $y = 2(x - 1)^2 + 4$? Enter (x, y).', '{"accept":["(4,22)"]}', '["Shift right 1, then double the y-value, then add 4."]', '$(3, 9) \to (4, 9) \to (4, 18) \to (4, 22)$. Check: $2(3)^2 + 4 = 22$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96decbbb3f82f5', 'les_d25fe88520a9bc', 5, 'review', 'multiple_choice', 3, 'The graph of $y = \sqrt{x}$ is transformed to $y = \sqrt{-x} + 2$. Which point is on the new graph?', '{"choices":["(4, 4)","(−4, 4)","(4, 0)","(−4, 0)"],"answer":1}', '["$\\sqrt{-x}$ reflects across the y-axis: $(4, 2)$ on $\\sqrt{x}$ becomes $(-4, 2)$."]', '$(4, 2) \to (-4, 2) \to (-4, 4)$. Check: $\sqrt{4} + 2 = 4$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_d25fe88520a9bc', 'subj_math', 'function-transformations', 'Function transformations', 'Shifts, reflections and stretches of a graph produced by changing a function''s formula.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d25fe88520a9bc', (SELECT id FROM concepts WHERE slug = 'function-transformations'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d25fe88520a9bc', (SELECT id FROM formulas WHERE slug = 'vertex-form'), 1);

-- Lesson: ideal-gas-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_292bab1dea096c', 'ideal-gas-law', 'The ideal gas law', 'Relate pressure, volume, temperature and amount of a gas with PV = nRT, and recognize when real gases depart from it.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_87fdaba793c9ac', 'les_292bab1dea096c', 1, 'Use the ideal gas law to find an unknown property of a gas.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cb933d29cf2f99', 'les_292bab1dea096c', 2, 'Derive Boyle''s, Charles''s and Gay-Lussac''s laws as special cases.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f6df1e40ea3faf', 'les_292bab1dea096c', 3, 'Convert temperatures to kelvin and choose R with consistent units.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f3f9ae39c7c235', 'les_292bab1dea096c', 4, 'Explain the assumptions of the ideal gas model and when it fails.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87fdaba793c9ac', 'les_292bab1dea096c', 'learn', 1, 'formula', '{"latex":"PV = nRT","title":"The ideal gas law","note":"$R = 0.08206$ L·atm/(mol·K) or $8.314$ J/(mol·K). Temperature must be in kelvin."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cb933d29cf2f99', 'les_292bab1dea096c', 'learn', 2, 'text', '{"body":"The law combines four observations. At fixed $n$ and $T$, pressure and volume are inversely proportional (Boyle). At fixed $n$ and $P$, volume is proportional to absolute temperature (Charles). At fixed $n$ and $V$, pressure is proportional to absolute temperature (Gay-Lussac). And at fixed $P$ and $T$, volume is proportional to the amount of gas (Avogadro)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f6df1e40ea3faf', 'les_292bab1dea096c', 'learn', 3, 'definition', '{"term":"Ideal gas","body":"A model gas whose particles take up no volume and don''t attract or repel each other, colliding elastically. Real gases behave nearly ideally at low pressure and high temperature."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f3f9ae39c7c235', 'les_292bab1dea096c', 'learn', 4, 'worked_example', '{"title":"What volume does 0.500 mol of N₂ occupy at 25 °C and 1.20 atm?","steps":[{"latex":"T = 25 + 273.15 = 298.15\\ \\text{K}","explanation":"Always convert to kelvin."},{"latex":"V = \\frac{nRT}{P} = \\frac{(0.500)(0.08206)(298.15)}{1.20}","explanation":"Solve for V."},{"latex":"V \\approx 10.2\\ \\text{L}","explanation":"Units: mol × L·atm/(mol·K) × K ÷ atm = L."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7797e1fd229ead', 'les_292bab1dea096c', 'learn', 5, 'worked_example', '{"title":"A sealed 2.0 L can at 20 °C and 1.0 atm is heated to 300 °C. Find the new pressure.","steps":[{"latex":"\\frac{P_1}{T_1} = \\frac{P_2}{T_2}","explanation":"n and V are fixed, so P/T is constant."},{"latex":"P_2 = 1.0 \\times \\frac{573.15}{293.15}","explanation":"Both temperatures in kelvin."},{"latex":"P_2 \\approx 1.96\\ \\text{atm}","explanation":"Nearly double: this is why aerosol cans warn against heat."}],"check":"Using Celsius would give $1.0 \\times \\frac{300}{20} = 15$ atm, wildly wrong. Kelvin is required because pressure is proportional to absolute temperature."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b699640a3e8b73', 'les_292bab1dea096c', 'learn', 6, 'callout', '{"tone":"warning","title":"When gases aren''t ideal","body":"At high pressure, molecules are close enough that their own volume matters, and at low temperature their attractions pull them together. Both make real behavior deviate from $PV = nRT$. Polar gases such as ammonia deviate more than noble gases like helium."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d602b3400034c4', 'les_292bab1dea096c', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car airbags inflate in milliseconds from a reaction that produces a calculated number of moles of nitrogen gas; the bag''s volume is designed with $PV = nRT$. Weather balloons expand as they rise because outside pressure drops."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be01f26dfa7204', 'les_292bab1dea096c', 'experiment', 8, 'activity', '{"activity":"ideal-gas","title":"Change the conditions"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f13007b1e38a57', 'les_292bab1dea096c', 'experiment', 9, 'callout', '{"tone":"tip","title":"Investigate","body":"Hold temperature constant and halve the volume. What happens to pressure? Now hold pressure constant and double the kelvin temperature. Predict before you change each slider."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b3741886d0194f', 'les_292bab1dea096c', 'watch', 10, 'activity', '{"activity":"ideal-gas","title":"Walkthrough: the gas laws as special cases","steps":[{"title":"Starting point","body":"1.00 mol at 273 K in 22.4 L exerts about 1.00 atm.","params":{"n":1,"T":273.15,"V":22.4,"hold":"T"}},{"title":"Boyle''s law","body":"Halve the volume at constant temperature: the pressure doubles to about 2.00 atm.","params":{"n":1,"T":273.15,"V":11.2,"hold":"T"}},{"title":"Gay-Lussac''s law","body":"Back to 22.4 L, now at 546 K: doubling the kelvin temperature doubles the pressure.","params":{"n":1,"T":546.3,"V":22.4,"hold":"V"}},{"title":"Avogadro''s law","body":"Twice the gas at 273 K and 22.4 L: twice the pressure.","params":{"n":2,"T":273.15,"V":22.4,"hold":"V"}}]}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87fdaba793c9ac', 'les_292bab1dea096c', 1, 'practice', 'numeric', 1, 'Convert 27 °C to kelvin (use 273.15).', '{"answer":300.15,"tolerance":0.01,"unit":"K"}', '["Add 273.15."]', '$27 + 273.15 = 300.15$ K.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cb933d29cf2f99', 'les_292bab1dea096c', 2, 'practice', 'numeric', 2, 'How many moles of gas occupy 5.00 L at 2.00 atm and 300 K? Use R = 0.08206 and give three significant figures.', '{"answer":0.406,"tolerance":0.001,"unit":"mol"}', '["$n = \\frac{PV}{RT}$."]', '$n = \frac{(2.00)(5.00)}{(0.08206)(300)} = \frac{10.0}{24.62} \approx 0.406$ mol.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f6df1e40ea3faf', 'les_292bab1dea096c', 3, 'practice', 'numeric', 2, 'A gas occupies 4.0 L at 1.0 atm. At constant temperature, what volume does it occupy at 2.5 atm?', '{"answer":1.6,"tolerance":0.01,"unit":"L"}', '["Boyle: $P_1V_1 = P_2V_2$."]', '$V_2 = \frac{1.0 \times 4.0}{2.5} = 1.6$ L.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f3f9ae39c7c235', 'les_292bab1dea096c', 4, 'practice', 'multiple_choice', 2, 'At constant pressure, a balloon''s temperature rises from 200 K to 400 K. Its volume:', '{"choices":["Halves","Doubles","Quadruples","Stays the same"],"answer":1}', '["Charles''s law: V ∝ T in kelvin."]', 'Doubling the absolute temperature doubles the volume.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7797e1fd229ead', 'les_292bab1dea096c', 5, 'review', 'multiple_choice', 3, 'Under which conditions does a real gas behave most like an ideal gas?', '{"choices":["High P, low T","Low P, high T","High P, high T","Low P, low T"],"answer":1}', '["When are particles far apart and moving fast?"]', 'At low pressure the particles'' own volume is negligible; at high temperature their attractions matter little.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b699640a3e8b73', 'les_292bab1dea096c', 6, 'review', 'numeric', 3, 'What is the molar mass of a gas if 1.60 g occupies 1.12 L at 273.15 K and 1.00 atm? (R = 0.08206; three significant figures.)', '{"answer":32,"tolerance":0.2,"unit":"g/mol"}', '["Find $n$ with $PV = nRT$, then $M = \\frac{m}{n}$."]', '$n = \frac{(1.00)(1.12)}{(0.08206)(273.15)} \approx 0.0500$ mol, so $M = \frac{1.60}{0.0500} \approx 32.0$ g/mol (consistent with O₂).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_026fce6cafe2d5', 'subj_chem', 'gas-laws', 'Gas laws', 'Relationships among pressure, volume, temperature and amount of a gas.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_292bab1dea096c', (SELECT id FROM concepts WHERE slug = 'gas-laws'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_f582b901a5ad39', 'subj_chem', 'kinetic-molecular-theory', 'Kinetic molecular theory', 'A model of gases as tiny particles in constant random motion with elastic collisions.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_292bab1dea096c', (SELECT id FROM concepts WHERE slug = 'kinetic-molecular-theory'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_292bab1dea096c', (SELECT id FROM formulas WHERE slug = 'ideal-gas-law'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_292bab1dea096c', (SELECT id FROM formulas WHERE slug = 'combined-gas-law'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_292bab1dea096c', (SELECT id FROM formulas WHERE slug = 'celsius-to-kelvin'), 3);

-- Lesson: law-of-large-numbers
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ed620a9391ea1a', 'law-of-large-numbers', 'Simulation and the law of large numbers', 'Estimate probabilities by simulation and see why relative frequencies settle down only over many trials.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c2b96760698845', 'les_ed620a9391ea1a', 1, 'Distinguish theoretical probability from relative frequency.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fd86c480d37eac', 'les_ed620a9391ea1a', 2, 'Use a simulation to estimate a probability.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d975cc07517170', 'les_ed620a9391ea1a', 3, 'Explain what the law of large numbers does and does not say.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c2b96760698845', 'les_ed620a9391ea1a', 'learn', 1, 'definition', '{"term":"Probability","body":"The proportion of times an outcome would occur in a very long series of repetitions of a random process. It is always between 0 and 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd86c480d37eac', 'les_ed620a9391ea1a', 'learn', 2, 'definition', '{"term":"Relative frequency","body":"In an actual series of trials, the number of times an outcome happened divided by the number of trials."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d975cc07517170', 'les_ed620a9391ea1a', 'learn', 3, 'text', '{"body":"When two fair dice are rolled, there are 36 equally likely ordered outcomes. Six of them sum to 7: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1). So the theoretical probability of a sum of 7 is $\\frac{6}{36} = \\frac{1}{6} \\approx 0.167$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6344dacd99a694', 'les_ed620a9391ea1a', 'learn', 4, 'text', '{"body":"Roll the dice ten times and you might see a 7 zero times or four times. Short runs are unpredictable. The law of large numbers says that as the number of trials grows, the relative frequency of an outcome gets closer and closer to its probability."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_03fa206a6a7df3', 'les_ed620a9391ea1a', 'learn', 5, 'callout', '{"tone":"warning","title":"The gambler''s fallacy","body":"The law of large numbers does not mean outcomes \"balance out\" in the short run. After five rolls without a 7, the chance of a 7 on the next roll is still $\\frac{1}{6}$. Dice have no memory; the early streak just becomes a smaller share of a growing total."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d0a531262d5d9a', 'les_ed620a9391ea1a', 'learn', 6, 'worked_example', '{"title":"Design a simulation for: \"a basketball player who makes 70% of free throws takes 5 shots; how likely is she to make at least 4?\"","steps":[{"latex":"\\text{digits } 0\\text{–}6 = \\text{make},\\ 7\\text{–}9 = \\text{miss}","explanation":"Assign random digits so each shot has a 70% chance."},{"latex":"\\text{one trial} = 5 \\text{ random digits}","explanation":"Count the makes in each group of five."},{"latex":"\\text{repeat many times}","explanation":"The proportion of trials with 4 or 5 makes estimates the probability."}],"check":"The exact binomial answer is $\\binom{5}{4}(0.7)^4(0.3) + (0.7)^5 \\approx 0.528$; a simulation with thousands of trials should land close to it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3ba81335943ba2', 'les_ed620a9391ea1a', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Insurance companies can''t predict whether one driver will crash, but across millions of policies the rate is very stable. That stability is the law of large numbers, and it''s why insurance can be priced at all."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ee9a7d68cb2ff', 'les_ed620a9391ea1a', 'experiment', 8, 'activity', '{"activity":"dice-simulation","title":"Roll two dice thousands of times"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8240161af2ce15', 'les_ed620a9391ea1a', 'experiment', 9, 'callout', '{"tone":"tip","title":"Investigate","body":"Reset and roll 10 times, then 100, then 10,000. Write down the relative frequency of a sum of 7 each time. How far is each from $\\frac{1}{6}$? Which sum is least common, and why?"}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c2b96760698845', 'les_ed620a9391ea1a', 1, 'practice', 'numeric', 1, 'Two fair dice are rolled. What is the probability that the sum is 8? Give a decimal to three places.', '{"answer":0.139,"tolerance":0.001}', '["Count the ordered pairs that add to 8."]', '(2,6), (3,5), (4,4), (5,3), (6,2): 5 of 36, so $\frac{5}{36} \approx 0.139$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fd86c480d37eac', 'les_ed620a9391ea1a', 2, 'practice', 'multiple_choice', 1, 'A coin lands heads 7 times in 10 flips. What does the law of large numbers predict about the next 10,000 flips?', '{"choices":["Tails will come up more often to make up for it.","The proportion of heads will likely be close to 0.5.","Heads will continue at about 70%.","Nothing can be said."],"answer":1}', '["Each flip is independent."]', 'Over many flips the relative frequency approaches the probability, 0.5. There is no "catching up"; the first 10 flips just matter less and less.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d975cc07517170', 'les_ed620a9391ea1a', 3, 'practice', 'numeric', 2, 'In a simulation, an event happened 412 times in 2,500 trials. What is the relative frequency?', '{"answer":0.1648,"tolerance":0.0001}', '["Divide the count by the number of trials."]', '$\frac{412}{2500} = 0.1648$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6344dacd99a694', 'les_ed620a9391ea1a', 4, 'practice', 'multiple_choice', 2, 'Which sum of two dice is most likely?', '{"choices":["2","6","7","12"],"answer":2}', '["Which sum can be made in the most ways?"]', '7 can be made 6 ways, more than any other sum.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_03fa206a6a7df3', 'les_ed620a9391ea1a', 5, 'review', 'numeric', 3, 'A spinner lands on red with probability 0.3. In 400 spins, about how many reds would you expect?', '{"answer":120}', '["Expected count = n · p."]', '$400 \times 0.3 = 120$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a88397b662aed6', 'subj_math', 'probability', 'Probability', 'The long-run relative frequency with which an outcome of a random process occurs.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ed620a9391ea1a', (SELECT id FROM concepts WHERE slug = 'probability'));

-- Lesson: limiting-reactant
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_03e6c5938fb573', 'limiting-reactant', 'Limiting reactant and percent yield', 'Use mole ratios to find which reactant runs out first, how much product can form, what''s left over, and the percent yield.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fe6dc1501c49d8', 'les_03e6c5938fb573', 1, 'Convert between mass and moles using molar mass.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eec954c6149fcc', 'les_03e6c5938fb573', 2, 'Identify the limiting and excess reactants from given amounts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_814e13718c2c81', 'les_03e6c5938fb573', 3, 'Calculate theoretical yield, leftover excess reactant and percent yield.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe6dc1501c49d8', 'les_03e6c5938fb573', 'learn', 1, 'text', '{"body":"A balanced equation is a recipe in moles. $2\\text{H}_2 + \\text{O}_2 \\rightarrow 2\\text{H}_2\\text{O}$ says that 2 mol of hydrogen react with exactly 1 mol of oxygen to make 2 mol of water. If you have more of one reactant than the recipe needs, the other runs out first and limits how much product you can make."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eec954c6149fcc', 'les_03e6c5938fb573', 'learn', 2, 'definition', '{"term":"Limiting reactant","body":"The reactant that is completely used up first. It determines the maximum amount of product, the theoretical yield. The other reactant is in excess."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_814e13718c2c81', 'les_03e6c5938fb573', 'learn', 3, 'formula', '{"latex":"n = \\frac{m}{M}","title":"Mass to moles","note":"Molar masses: H₂ = 2.016 g/mol, O₂ = 32.00 g/mol, H₂O = 18.02 g/mol."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ad652fc1d5098b', 'les_03e6c5938fb573', 'learn', 4, 'worked_example', '{"title":"10.0 g H₂ reacts with 64.0 g O₂. Find the limiting reactant and the mass of water formed.","steps":[{"latex":"n_{\\text{H}_2} = \\frac{10.0}{2.016} = 4.96\\ \\text{mol},\\quad n_{\\text{O}_2} = \\frac{64.0}{32.00} = 2.00\\ \\text{mol}","explanation":"Convert to moles."},{"latex":"\\text{O}_2 \\text{ needed for all H}_2 = \\frac{4.96}{2} = 2.48\\ \\text{mol}","explanation":"The ratio is 2 H₂ : 1 O₂."},{"latex":"2.48 > 2.00 \\Rightarrow \\text{O}_2 \\text{ is limiting}","explanation":"There isn''t enough oxygen."},{"latex":"n_{\\text{H}_2\\text{O}} = 2 \\times 2.00 = 4.00\\ \\text{mol}","explanation":"1 O₂ makes 2 H₂O."},{"latex":"m = 4.00 \\times 18.02 = 72.1\\ \\text{g}","explanation":"Theoretical yield."}],"check":"Mass is conserved: H₂ used $= 4.00$ mol $\\times 2.016 = 8.06$ g, so $8.06 + 64.0 = 72.1$ g of water, with $10.0 - 8.06 = 1.94$ g of H₂ left over."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4d66701d062ec0', 'les_03e6c5938fb573', 'learn', 5, 'callout', '{"tone":"tip","title":"A quick test","body":"Divide each reactant''s moles by its coefficient. The smallest result is the limiting reactant. Here H₂: $\\frac{4.96}{2} = 2.48$; O₂: $\\frac{2.00}{1} = 2.00$, so O₂ limits."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9341fcc8c9f52b', 'les_03e6c5938fb573', 'learn', 6, 'formula', '{"latex":"\\text{percent yield} = \\frac{\\text{actual}}{\\text{theoretical}} \\times 100\\%","title":"Percent yield","note":"Real reactions lose product to side reactions, incomplete reaction and handling, so the actual yield is usually less than theoretical."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_49b80731a8a2c8', 'les_03e6c5938fb573', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pharmaceutical manufacturers add the cheaper reagent in excess so the expensive one is fully converted. Rocket engines are tuned to a fuel-oxidizer ratio for the same reason."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7595d592941ef4', 'les_03e6c5938fb573', 'experiment', 8, 'activity', '{"activity":"stoichiometry","title":"Mix hydrogen and oxygen"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f66c4732cf4901', 'les_03e6c5938fb573', 'experiment', 9, 'callout', '{"tone":"tip","title":"Investigate","body":"Find the exact amounts of H₂ and O₂ (in moles) that leave nothing over. What ratio do they always have? Then give 3 mol H₂ and 3 mol O₂: which is limiting and how much is left?"}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fe6dc1501c49d8', 'les_03e6c5938fb573', 1, 'practice', 'numeric', 1, 'How many moles are in 36.04 g of water (18.02 g/mol)?', '{"answer":2,"tolerance":0.001,"unit":"mol"}', '["$n = m/M$."]', '$36.04 / 18.02 = 2.000$ mol.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eec954c6149fcc', 'les_03e6c5938fb573', 2, 'practice', 'multiple_choice', 2, 'For $2\text{H}_2 + \text{O}_2 \rightarrow 2\text{H}_2\text{O}$, which is limiting with 3.0 mol H₂ and 2.0 mol O₂?', '{"choices":["H₂","O₂","Neither","Both"],"answer":0}', '["Divide moles by coefficients: H₂ 3.0/2, O₂ 2.0/1."]', 'H₂: 1.5; O₂: 2.0. The smaller value is H₂, so H₂ runs out first.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_814e13718c2c81', 'les_03e6c5938fb573', 3, 'practice', 'numeric', 2, 'With 3.0 mol H₂ and 2.0 mol O₂, how many moles of water form?', '{"answer":3,"tolerance":0.001,"unit":"mol"}', '["Use the limiting reactant, H₂: 2 H₂ → 2 H₂O."]', '3.0 mol H₂ × (2 H₂O / 2 H₂) = 3.0 mol H₂O.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ad652fc1d5098b', 'les_03e6c5938fb573', 4, 'practice', 'numeric', 2, 'In that reaction, how many moles of O₂ are left over?', '{"answer":0.5,"tolerance":0.001,"unit":"mol"}', '["3.0 mol H₂ uses 1.5 mol O₂."]', '$2.0 - 1.5 = 0.5$ mol O₂ remains.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4d66701d062ec0', 'les_03e6c5938fb573', 5, 'review', 'numeric', 3, 'A reaction has a theoretical yield of 72.1 g, but 65.0 g is collected. What is the percent yield? (one decimal)', '{"answer":90.2,"tolerance":0.1,"unit":"%"}', '["actual ÷ theoretical × 100."]', '$\frac{65.0}{72.1} \times 100 \approx 90.2\%$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_88b712726f4587', 'subj_chem', 'stoichiometry', 'Stoichiometry', 'Quantitative relationships between reactants and products in a balanced equation.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_03e6c5938fb573', (SELECT id FROM concepts WHERE slug = 'stoichiometry'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ddbf85ce66c8d4', 'subj_chem', 'the-mole', 'The mole', '6.022 × 10²³ particles; the chemist''s counting unit.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_03e6c5938fb573', (SELECT id FROM concepts WHERE slug = 'the-mole'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_03e6c5938fb573', (SELECT id FROM formulas WHERE slug = 'molar-mass-moles'), 1);
