-- Lesson: newtons-second-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bf46151614f7f1', 'newtons-second-law', 'Newton''s second law', 'Relate net force, mass and acceleration, draw free-body diagrams, and apply F = ma along an incline with friction.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_083b1a0f6c6e33', 'les_bf46151614f7f1', 1, 'State Newton''s second law and use it to find acceleration or force.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8e8e9fc7bf2464', 'les_bf46151614f7f1', 2, 'Draw a free-body diagram and find the net force by components.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_13caf249d1f53a', 'les_bf46151614f7f1', 3, 'Analyze an object on an incline with and without friction.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_083b1a0f6c6e33', 'les_bf46151614f7f1', 'learn', 1, 'formula', '{"latex":"\\vec{F}_{\\text{net}} = m\\vec{a}","title":"Newton''s second law","note":"The acceleration of an object is in the direction of the net force, with size proportional to the force and inversely proportional to the mass. Units: 1 N = 1 kg·m/s²."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e8e9fc7bf2464', 'les_bf46151614f7f1', 'learn', 2, 'definition', '{"term":"Net force","body":"The vector sum of all forces acting on an object. Forces from the object on other things do not belong in its sum."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_13caf249d1f53a', 'les_bf46151614f7f1', 'learn', 3, 'definition', '{"term":"Free-body diagram","body":"A sketch of one object with an arrow for every force acting on it: gravity $mg$, normal force $F_N$, friction, tension, applied pushes and pulls."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_942668f1642651', 'les_bf46151614f7f1', 'learn', 4, 'worked_example', '{"title":"A 1200 kg car accelerates from rest to 24 m/s in 8 s. What net force acts on it?","steps":[{"latex":"a = \\frac{\\Delta v}{\\Delta t} = \\frac{24}{8} = 3\\ \\text{m/s}^2","explanation":"Average acceleration."},{"latex":"F_{\\text{net}} = ma = 1200 \\times 3 = 3600\\ \\text{N}","explanation":"Second law."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8adf4ebf6deb02', 'les_bf46151614f7f1', 'learn', 5, 'text', '{"body":"On an incline it helps to tilt the axes: one parallel to the slope and one perpendicular. Gravity $mg$ splits into $mg\\sin\\theta$ down the slope and $mg\\cos\\theta$ into the slope. The normal force balances the perpendicular part, so $F_N = mg\\cos\\theta$, and only the parallel parts produce acceleration."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8f8d614aeffb82', 'les_bf46151614f7f1', 'learn', 6, 'worked_example', '{"title":"A 5 kg box slides down a 30° ramp with $\\mu_k = 0.20$. Find its acceleration.","steps":[{"latex":"mg\\sin\\theta = 5(9.8)(0.5) = 24.5\\ \\text{N}","explanation":"Gravity''s component down the slope."},{"latex":"F_N = mg\\cos\\theta = 5(9.8)(0.866) \\approx 42.4\\ \\text{N}","explanation":"Perpendicular balance."},{"latex":"f_k = \\mu_k F_N = 0.20(42.4) \\approx 8.49\\ \\text{N}","explanation":"Kinetic friction, up the slope."},{"latex":"a = \\frac{24.5 - 8.49}{5} \\approx 3.20\\ \\text{m/s}^2","explanation":"Net force along the slope divided by mass."}],"check":"Mass cancels if you write it symbolically: $a = g(\\sin\\theta - \\mu_k\\cos\\theta)$, so any box with the same $\\mu_k$ has the same acceleration."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c305f65d72df4', 'les_bf46151614f7f1', 'learn', 7, 'callout', '{"tone":"warning","title":"Static friction is different","body":"If the box isn''t sliding, static friction adjusts to whatever value is needed, up to a maximum of $\\mu_s F_N$. The box starts to slide only when $\\tan\\theta > \\mu_s$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ae6ae01284b262', 'les_bf46151614f7f1', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Truck ramps, ski slopes and conveyor belts are designed with these components. A runaway-truck ramp uses gravel to raise the friction coefficient so trucks stop safely."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8d8f4b8a8f87ea', 'les_bf46151614f7f1', 'experiment', 9, 'activity', '{"activity":"forces-incline","title":"Forces on an incline"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ab2d86feafd36', 'les_bf46151614f7f1', 'experiment', 10, 'callout', '{"tone":"tip","title":"Investigate","body":"Set friction to 0.30. Find the steepest angle at which the box stays at rest. Does it change when you double the mass? Compare your answer with $\\tan^{-1}(0.30)$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_083b1a0f6c6e33', 'les_bf46151614f7f1', 1, 'practice', 'numeric', 1, 'A 2 kg cart has a net force of 10 N. What is its acceleration?', '{"answer":5,"unit":"m/s²"}', '["$a = \\frac{F}{m}$."]', '$a = \frac{10}{2} = 5$ m/s².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8e8e9fc7bf2464', 'les_bf46151614f7f1', 2, 'practice', 'numeric', 1, 'What net force accelerates a 70 kg sprinter at 4 m/s²?', '{"answer":280,"unit":"N"}', '["$F = ma$."]', '$70 \times 4 = 280$ N.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_13caf249d1f53a', 'les_bf46151614f7f1', 3, 'practice', 'multiple_choice', 2, 'Two forces act on a 4 kg block: 12 N east and 4 N west. What is its acceleration?', '{"choices":["4 m/s² east","2 m/s² east","3 m/s² west","1 m/s² east"],"answer":1}', '["Find the net force first."]', '$F_{\text{net}} = 12 - 4 = 8$ N east, so $a = \frac{8}{4} = 2$ m/s² east.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_942668f1642651', 'les_bf46151614f7f1', 4, 'practice', 'numeric', 2, 'A box slides down a frictionless 25° incline. What is its acceleration? Use g = 9.8 m/s², round to two decimals.', '{"answer":4.14,"tolerance":0.01,"unit":"m/s²"}', '["Without friction, $a = g\\sin\\theta$."]', '$9.8\sin 25° \approx 9.8(0.4226) \approx 4.14$ m/s².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8adf4ebf6deb02', 'les_bf46151614f7f1', 5, 'practice', 'numeric', 3, 'A 10 kg crate is pushed across a level floor with 60 N. $\mu_k = 0.35$. Find its acceleration (g = 9.8 m/s², two decimals).', '{"answer":2.57,"tolerance":0.01,"unit":"m/s²"}', '["$F_N = mg = 98$ N, so friction is $0.35 \\times 98$."]', '$f_k = 34.3$ N, $F_{\text{net}} = 60 - 34.3 = 25.7$ N, $a = 2.57$ m/s².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8f8d614aeffb82', 'les_bf46151614f7f1', 6, 'review', 'multiple_choice', 3, 'A block rests on a ramp. The angle is slowly increased until the block just starts to slide at 35°. What is $\mu_s$?', '{"choices":["0.57","0.70","0.82","0.35"],"answer":1}', '["At the threshold, $mg\\sin\\theta = \\mu_s mg\\cos\\theta$."]', '$\mu_s = \tan 35° \approx 0.70$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_c9cbf9c596594d', 'subj_phys', 'newtons-laws', 'Newton''s laws of motion', 'Three laws relating forces to changes in motion.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bf46151614f7f1', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_cfa7bd3f4446d1', 'subj_phys', 'free-body-diagrams', 'Free-body diagrams', 'Diagrams showing every force acting on one object.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bf46151614f7f1', (SELECT id FROM concepts WHERE slug = 'free-body-diagrams'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bf46151614f7f1', (SELECT id FROM formulas WHERE slug = 'newtons-second-law'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bf46151614f7f1', (SELECT id FROM formulas WHERE slug = 'kinetic-friction'), 2);

-- Lesson: normal-distribution
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9e351cc0887182', 'normal-distribution', 'The normal distribution', 'Describe bell-shaped distributions with a mean and standard deviation, standardize values with z-scores, and find probabilities.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e6ac6f1e97b758', 'les_9e351cc0887182', 1, 'Describe the shape, center and spread of a normal distribution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_65cdd880d2e97a', 'les_9e351cc0887182', 2, 'Apply the empirical (68–95–99.7) rule.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fa53e98978e9f8', 'les_9e351cc0887182', 3, 'Compute and interpret z-scores.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_22ecca04e3ffbc', 'les_9e351cc0887182', 4, 'Find the proportion of a normal distribution in an interval.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e6ac6f1e97b758', 'les_9e351cc0887182', 'learn', 1, 'text', '{"body":"Many measurements cluster around an average with fewer and fewer values further away: heights of adults, errors in repeated measurements, scores on large standardized tests. When a histogram of such data is smooth and symmetric, a normal curve models it well."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_65cdd880d2e97a', 'les_9e351cc0887182', 'learn', 2, 'definition', '{"term":"Normal distribution","body":"A continuous distribution with a symmetric bell-shaped density curve, written $N(\\mu, \\sigma)$. The mean $\\mu$ sets the center (which is also the median and mode) and the standard deviation $\\sigma > 0$ sets the spread."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa53e98978e9f8', 'les_9e351cc0887182', 'learn', 3, 'text', '{"body":"Probability is area under the density curve. The total area is 1, so the area between two values is the proportion of the distribution, or the probability that a randomly chosen value falls, between them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22ecca04e3ffbc', 'les_9e351cc0887182', 'learn', 4, 'callout', '{"tone":"note","title":"The empirical rule","body":"In any normal distribution about 68% of values are within $1\\sigma$ of the mean, about 95% within $2\\sigma$, and about 99.7% within $3\\sigma$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_31563e0d54292b', 'les_9e351cc0887182', 'learn', 5, 'formula', '{"latex":"z = \\frac{x - \\mu}{\\sigma}","title":"Standardizing","note":"A z-score converts any normal distribution to the standard normal $N(0, 1)$, so one table or calculator function works for all of them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1536a7c793a708', 'les_9e351cc0887182', 'learn', 6, 'worked_example', '{"title":"SAT-style scores follow $N(500, 100)$. What proportion score above 650?","steps":[{"latex":"z = \\frac{650 - 500}{100} = 1.5","explanation":"650 is 1.5 standard deviations above the mean."},{"latex":"P(Z < 1.5) \\approx 0.9332","explanation":"From a standard normal table or calculator."},{"latex":"P(Z > 1.5) \\approx 1 - 0.9332 = 0.0668","explanation":"The area to the right is 1 minus the area to the left."}],"check":"About 6.7% score above 650. That''s a little less than the 16% above $1\\sigma$, which makes sense since 650 is further out."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f2db5aecf99198', 'les_9e351cc0887182', 'learn', 7, 'worked_example', '{"title":"Heights of a population are $N(170, 8)$ cm. What proportion are between 162 and 186 cm?","steps":[{"latex":"z_1 = \\frac{162 - 170}{8} = -1,\\quad z_2 = \\frac{186 - 170}{8} = 2","explanation":"Standardize both endpoints."},{"latex":"P(-1 < Z < 2) = 0.9772 - 0.1587","explanation":"Subtract the left areas."},{"latex":"\\approx 0.8186","explanation":"About 82%."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd661eecc4eb09', 'les_9e351cc0887182', 'learn', 8, 'callout', '{"tone":"warning","title":"Check before you assume normal","body":"Not every distribution is normal. Incomes and waiting times are usually skewed right. Look at a histogram or normal probability plot before using these methods."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_40506afb2b79ff', 'les_9e351cc0887182', 'experiment', 9, 'activity', '{"activity":"normal-distribution","title":"Shade an interval"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4df0ccbe45c0aa', 'les_9e351cc0887182', 'experiment', 10, 'callout', '{"tone":"tip","title":"Investigate","body":"Set the interval to $\\mu \\pm \\sigma$ and change $\\sigma$. Does the shaded probability change? Why not? Then find the interval centered at $\\mu$ that holds 95%."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2abffc9907defd', 'les_9e351cc0887182', 'watch', 11, 'activity', '{"activity":"normal-distribution","title":"Walkthrough: the empirical rule","steps":[{"title":"One standard deviation","body":"Between μ − σ and μ + σ lies about 68% of the area.","params":{"mu":0,"sigma":1,"lo":-1,"hi":1}},{"title":"Two","body":"Within two standard deviations: about 95%.","params":{"mu":0,"sigma":1,"lo":-2,"hi":2}},{"title":"Three","body":"Within three: about 99.7%. Values beyond 3σ are rare.","params":{"mu":0,"sigma":1,"lo":-3,"hi":3}},{"title":"Any normal curve","body":"The same percentages hold for N(100, 15): 85 to 115 contains about 68%.","params":{"mu":100,"sigma":15,"lo":85,"hi":115}}]}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e6ac6f1e97b758', 'les_9e351cc0887182', 1, 'practice', 'numeric', 1, 'A value of 74 comes from $N(60, 7)$. What is its z-score?', '{"answer":2}', '["$z = \\frac{x - \\mu}{\\sigma}$."]', '$z = \frac{74 - 60}{7} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_65cdd880d2e97a', 'les_9e351cc0887182', 2, 'practice', 'multiple_choice', 1, 'About what percent of a normal distribution lies within 2 standard deviations of the mean?', '{"choices":["50%","68%","95%","99.7%"],"answer":2}', '["Recall the empirical rule."]', 'About 95% lies within $\mu \pm 2\sigma$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa53e98978e9f8', 'les_9e351cc0887182', 3, 'practice', 'numeric', 2, 'Test scores are $N(75, 10)$. Using the empirical rule, about what percent score above 85?', '{"answer":16,"tolerance":0.5,"unit":"%"}', '["85 is one standard deviation above the mean.","68% are within 1σ, so 32% are outside, split evenly between the tails."]', '$(100\% - 68\%) / 2 = 16\%$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22ecca04e3ffbc', 'les_9e351cc0887182', 4, 'practice', 'numeric', 2, 'For $N(500, 100)$, find $P(X < 380)$ to three decimals.', '{"answer":0.115,"tolerance":0.002}', '["$z = \\frac{380 - 500}{100} = -1.2$."]', '$P(Z < -1.2) \approx 0.1151$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_31563e0d54292b', 'les_9e351cc0887182', 5, 'review', 'numeric', 3, 'Lightbulb lifetimes are $N(1200, 150)$ hours. What lifetime marks the top 10%? Round to the nearest hour.', '{"answer":1392,"tolerance":2,"unit":"h"}', '["Find $z$ with 90% of the area to its left: $z \\approx 1.2816$.","Then $x = \\mu + z\\sigma$."]', '$x = 1200 + 1.2816(150) \approx 1392$ hours.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9e351cc0887182', 'subj_math', 'normal-distribution', 'Normal distribution', 'A symmetric, bell-shaped probability distribution described by its mean and standard deviation.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9e351cc0887182', (SELECT id FROM concepts WHERE slug = 'normal-distribution'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2485df8d7067e8', 'subj_math', 'z-scores', 'z-scores', 'The number of standard deviations a value lies from the mean.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9e351cc0887182', (SELECT id FROM concepts WHERE slug = 'z-scores'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9e351cc0887182', (SELECT id FROM formulas WHERE slug = 'z-score'), 1);

-- Lesson: periodic-trends
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_763d9265e12378', 'periodic-trends', 'Periodic trends', 'Explain trends in atomic radius, ionization energy and electronegativity using nuclear charge, shielding and energy levels.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_22be03331129fa', 'les_763d9265e12378', 1, 'Describe how atomic radius, first ionization energy and electronegativity change across a period and down a group.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f9c9c922945fc7', 'les_763d9265e12378', 2, 'Explain the trends using effective nuclear charge and electron shells.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6a726fe5f7ca93', 'les_763d9265e12378', 3, 'Recognize common exceptions in ionization energy.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_22be03331129fa', 'les_763d9265e12378', 'learn', 1, 'text', '{"body":"The periodic table is organized so that elements with similar outer-electron arrangements line up in columns. Because properties depend on those outer electrons, they change in predictable ways as you move across a row (period) or down a column (group)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9c9c922945fc7', 'les_763d9265e12378', 'learn', 2, 'definition', '{"term":"Effective nuclear charge","body":"The net positive charge an outer electron actually feels: the nuclear charge minus the shielding by inner electrons. It increases across a period because protons are added while the number of inner-shell electrons stays the same."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6a726fe5f7ca93', 'les_763d9265e12378', 'learn', 3, 'text', '{"body":"Across a period, effective nuclear charge rises and electrons are added to the same main energy level. The nucleus pulls them closer, so atomic radius decreases. Down a group, each step adds a new energy level farther from the nucleus, and inner electrons shield the outer ones, so radius increases."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa55c715b84451', 'les_763d9265e12378', 'learn', 4, 'definition', '{"term":"First ionization energy","body":"The energy needed to remove the outermost electron from a gaseous atom. It generally increases across a period and decreases down a group: the opposite of atomic radius, since closer electrons are held more tightly."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6d9aa02adb0e0a', 'les_763d9265e12378', 'learn', 5, 'definition', '{"term":"Electronegativity","body":"A measure of how strongly an atom attracts shared electrons in a bond (Pauling scale). Fluorine is the most electronegative element at 3.98. Electronegativity increases across a period and decreases down a group; noble gases are usually left out because they rarely form bonds."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_566381809adc06', 'les_763d9265e12378', 'learn', 6, 'worked_example', '{"title":"Rank Na, Mg and K by atomic radius","steps":[{"latex":"\\text{Na, Mg: period 3;\\ K: period 4}","explanation":"K has an extra energy level."},{"latex":"\\text{Mg} < \\text{Na}","explanation":"Across period 3, Mg has more protons pulling the same shell inward."},{"latex":"\\text{Mg} < \\text{Na} < \\text{K}","explanation":"Smallest to largest."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9316c5aeb76c35', 'les_763d9265e12378', 'learn', 7, 'callout', '{"tone":"warning","title":"Exceptions in ionization energy","body":"First ionization energy dips from Be to B and from N to O. Boron''s outer electron is in a 2p orbital, slightly higher in energy than 2s. In oxygen, one 2p orbital holds a pair of electrons that repel each other, making one easier to remove."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_308c739b85cfdb', 'les_763d9265e12378', 'learn', 8, 'callout', '{"tone":"application","title":"Why it matters","body":"Trends predict reactivity: cesium, with a large radius and low ionization energy, reacts violently with water; fluorine, small and highly electronegative, is the most reactive nonmetal. Electronegativity differences predict whether bonds are ionic, polar covalent or nonpolar."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4753d303d0a3ee', 'les_763d9265e12378', 'experiment', 9, 'activity', '{"activity":"periodic-trends","title":"Color the table by property","params":{"property":"radius"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0350389db9bb05', 'les_763d9265e12378', 'experiment', 10, 'callout', '{"tone":"tip","title":"Investigate","body":"Switch between atomic radius and ionization energy. Which element has the largest radius among those shown? Find both ionization-energy dips in period 2 and in period 3."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_22be03331129fa', 'les_763d9265e12378', 1, 'practice', 'multiple_choice', 1, 'Which atom has the largest atomic radius?', '{"choices":["Li","Na","K","Rb"],"answer":3}', '["Moving down a group adds energy levels."]', 'Rb is lowest in group 1, so it has the most occupied energy levels.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f9c9c922945fc7', 'les_763d9265e12378', 2, 'practice', 'multiple_choice', 1, 'Which element has the highest electronegativity?', '{"choices":["O","F","Cl","N"],"answer":1}', '["It''s at the top right, excluding noble gases."]', 'Fluorine has the highest electronegativity of all elements (3.98).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6a726fe5f7ca93', 'les_763d9265e12378', 3, 'practice', 'multiple_choice', 2, 'Why does atomic radius decrease from Na to Cl?', '{"choices":["Electrons are added to new energy levels.","Effective nuclear charge increases while electrons fill the same level.","Shielding increases strongly across the period.","Atoms lose electrons across the period."],"answer":1}', '["What changes in the nucleus, and what stays the same in the electron shells?"]', 'Protons are added across the period, but the new electrons enter the same third shell and shield each other poorly, so the outer electrons are pulled closer.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa55c715b84451', 'les_763d9265e12378', 4, 'practice', 'multiple_choice', 2, 'Which has the larger first ionization energy: N or O?', '{"choices":["N","O","They are equal","Cannot be determined"],"answer":0}', '["Look for an exception to the general trend."]', 'N. Oxygen''s paired 2p electrons repel each other, so removing one takes less energy, an exception to the increasing trend.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6d9aa02adb0e0a', 'les_763d9265e12378', 5, 'review', 'multiple_choice', 3, 'Arrange Mg, S and Ba in order of increasing first ionization energy.', '{"choices":["Ba < Mg < S","S < Mg < Ba","Mg < Ba < S","Ba < S < Mg"],"answer":0}', '["Ba is far down the table; S is far right in period 3."]', 'Ba is lowest (large radius); within period 3, S is to the right of Mg and holds its electrons more tightly.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_763d9265e12378', 'subj_chem', 'periodic-trends', 'Periodic trends', 'Regular patterns in atomic properties across periods and down groups.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_763d9265e12378', (SELECT id FROM concepts WHERE slug = 'periodic-trends'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_e066721b0e2656', 'subj_chem', 'effective-nuclear-charge', 'Effective nuclear charge', 'The net positive charge felt by an electron after shielding by other electrons.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_763d9265e12378', (SELECT id FROM concepts WHERE slug = 'effective-nuclear-charge'));

-- Lesson: projectile-motion
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9e596b453bfd64', 'projectile-motion', 'Projectile motion', 'Treat horizontal and vertical motion separately to predict a projectile''s path, flight time, peak height and range.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b0b340a3f43087', 'les_9e596b453bfd64', 1, 'Resolve a launch velocity into horizontal and vertical components.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d0c49524930321', 'les_9e596b453bfd64', 2, 'Explain why horizontal velocity is constant and vertical acceleration is −g when air resistance is negligible.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_86e337cce3cde9', 'les_9e596b453bfd64', 3, 'Calculate flight time, maximum height and range.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0b340a3f43087', 'les_9e596b453bfd64', 'learn', 1, 'definition', '{"term":"Projectile","body":"An object moving through the air with only gravity acting on it after launch. In this lesson we ignore air resistance, which is a good approximation for dense, slow objects over short distances."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d0c49524930321', 'les_9e596b453bfd64', 'learn', 2, 'text', '{"body":"The key idea is independence: the horizontal and vertical parts of the motion don''t affect each other. Gravity pulls straight down, so it changes only the vertical velocity. Horizontally nothing pushes or pulls, so the horizontal velocity stays constant for the whole flight."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86e337cce3cde9', 'les_9e596b453bfd64', 'learn', 3, 'formula', '{"latex":"v_{0x} = v_0\\cos\\theta, \\qquad v_{0y} = v_0\\sin\\theta","title":"Launch components","note":"$\\theta$ is measured above the horizontal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_03fdd69ca7f5d8', 'les_9e596b453bfd64', 'learn', 4, 'formula', '{"latex":"x = v_{0x}\\,t, \\qquad y = y_0 + v_{0y}\\,t - \\tfrac{1}{2}g t^2","title":"Position at time t","note":"With $g \\approx 9.8$ m/s² near Earth''s surface, taking up as positive."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_622b6836b56726', 'les_9e596b453bfd64', 'learn', 5, 'worked_example', '{"title":"A ball is kicked at 20 m/s, 30° above level ground. Find flight time, peak height and range.","steps":[{"latex":"v_{0x} = 20\\cos 30° \\approx 17.32,\\quad v_{0y} = 20\\sin 30° = 10","explanation":"Components in m/s."},{"latex":"t_{\\text{peak}} = \\frac{v_{0y}}{g} = \\frac{10}{9.8} \\approx 1.02\\ \\text{s}","explanation":"At the top, vertical velocity is zero."},{"latex":"H = \\frac{v_{0y}^2}{2g} = \\frac{100}{19.6} \\approx 5.10\\ \\text{m}","explanation":"Maximum height."},{"latex":"T = 2t_{\\text{peak}} \\approx 2.04\\ \\text{s}","explanation":"Landing at launch height: the flight is symmetric."},{"latex":"R = v_{0x}T \\approx 17.32 \\times 2.04 \\approx 35.3\\ \\text{m}","explanation":"Range = horizontal speed × time in the air."}],"check":"The range formula gives $R = \\frac{v_0^2\\sin 2\\theta}{g} = \\frac{400\\sin 60°}{9.8} \\approx 35.3$ m, the same answer."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e78c10c4830113', 'les_9e596b453bfd64', 'learn', 6, 'callout', '{"tone":"note","title":"Why 45° goes farthest","body":"On level ground, range is proportional to $\\sin 2\\theta$, which is largest at $2\\theta = 90°$. Complementary angles such as 30° and 60° give the same range: one is flatter and faster, the other higher and slower."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_918ac1c47118fd', 'les_9e596b453bfd64', 'learn', 7, 'callout', '{"tone":"warning","title":"Model limits","body":"Real projectiles feel air resistance, which reduces range and makes the path asymmetric; the best angle is usually less than 45°. A launch from above the landing point also changes the optimal angle. The simulator lets you add launch height but does not model drag."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e2757a586aa7f', 'les_9e596b453bfd64', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Long jumpers, basketball shots, water fountains and fireworks displays are all designed with these equations, then corrected for drag."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f5755bf2fc251a', 'les_9e596b453bfd64', 'experiment', 9, 'activity', '{"activity":"projectile","title":"Launch a projectile","params":{"g":9.8}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a8273f5830088a', 'les_9e596b453bfd64', 'experiment', 10, 'callout', '{"tone":"tip","title":"Investigate","body":"Find two different angles that land at exactly the same spot. Then raise the launch height to 10 m. Is 45° still the angle with the longest range? Change gravity to the Moon''s 1.6 m/s²: what happens to the range at the same speed and angle?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e69f4537019f68', 'les_9e596b453bfd64', 'watch', 11, 'activity', '{"activity":"projectile","title":"Walkthrough: one launch, two independent motions","steps":[{"title":"Launch","body":"20 m/s at 30°. The velocity splits into 17.3 m/s across and 10 m/s up.","params":{"speed":20,"angle":30,"height":0}},{"title":"Steeper","body":"At 60° the ball goes higher and stays up longer, but moves across more slowly. It lands at the same distance.","params":{"speed":20,"angle":60,"height":0}},{"title":"Best angle","body":"At 45° the trade-off is balanced and the range is greatest on level ground: about 40.8 m.","params":{"speed":20,"angle":45,"height":0}},{"title":"From a height","body":"Launched from 15 m up, the ball stays airborne longer and lands farther away.","params":{"speed":20,"angle":45,"height":15}}]}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b0b340a3f43087', 'les_9e596b453bfd64', 1, 'practice', 'numeric', 1, 'A ball is thrown at 15 m/s at 40° above horizontal. What is the horizontal component of its velocity? Round to two decimals.', '{"answer":11.49,"tolerance":0.01,"unit":"m/s"}', '["$v_{0x} = v_0\\cos\\theta$."]', '$15\cos 40° \approx 15(0.766) \approx 11.49$ m/s.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d0c49524930321', 'les_9e596b453bfd64', 2, 'practice', 'multiple_choice', 1, 'Ignoring air resistance, which quantity stays constant during a projectile''s flight?', '{"choices":["Vertical velocity","Horizontal velocity","Speed","Height"],"answer":1}', '["Which direction does gravity act in?"]', 'Gravity acts vertically, so only the vertical velocity changes. The horizontal velocity is constant.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_86e337cce3cde9', 'les_9e596b453bfd64', 3, 'practice', 'numeric', 2, 'A stone is thrown horizontally at 8 m/s from a 20 m cliff. How long is it in the air? Use g = 9.8 m/s² and round to two decimals.', '{"answer":2.02,"tolerance":0.01,"unit":"s"}', '["The initial vertical velocity is zero.","Solve $20 = \\tfrac{1}{2}(9.8)t^2$."]', '$t = \sqrt{\frac{2(20)}{9.8}} \approx 2.02$ s.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_03fdd69ca7f5d8', 'les_9e596b453bfd64', 4, 'practice', 'numeric', 2, 'For that stone, how far from the base of the cliff does it land? Round to one decimal.', '{"answer":16.2,"tolerance":0.1,"unit":"m"}', '["Horizontal distance = horizontal speed × time."]', '$8 \times 2.02 \approx 16.2$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_622b6836b56726', 'les_9e596b453bfd64', 5, 'practice', 'numeric', 3, 'What launch speed gives a 50 m range at 45° on level ground with g = 9.8 m/s²? Round to one decimal.', '{"answer":22.1,"tolerance":0.1,"unit":"m/s"}', '["$R = \\frac{v_0^2\\sin 90°}{g}$."]', '$v_0 = \sqrt{Rg} = \sqrt{490} \approx 22.1$ m/s.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e78c10c4830113', 'les_9e596b453bfd64', 6, 'review', 'multiple_choice', 3, 'Two balls leave a table at the same moment: A is dropped, B is launched horizontally. Which lands first?', '{"choices":["A","B","They land together","It depends on B''s speed"],"answer":2}', '["Compare their vertical motions."]', 'Both start with zero vertical velocity and fall with the same acceleration, so they hit the floor at the same time.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9e596b453bfd64', 'subj_phys', 'projectile-motion', 'Projectile motion', 'Two-dimensional motion under gravity alone, with independent horizontal and vertical components.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9e596b453bfd64', (SELECT id FROM concepts WHERE slug = 'projectile-motion'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_7291eb9f68564d', 'subj_phys', 'vectors', 'Vectors', 'Quantities with both magnitude and direction, combined by components.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9e596b453bfd64', (SELECT id FROM concepts WHERE slug = 'vectors'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9e596b453bfd64', (SELECT id FROM formulas WHERE slug = 'velocity-constant-acceleration'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9e596b453bfd64', (SELECT id FROM formulas WHERE slug = 'displacement-constant-acceleration'), 2);
