-- Lesson: pythagorean-theorem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0beaeb78870f01', 'pythagorean-theorem', 'The Pythagorean theorem and its converse', 'Relate the side lengths of right triangles, find missing sides, and test whether a triangle is right.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cf75559457d357', 'les_0beaeb78870f01', 1, 'State the Pythagorean theorem and identify the hypotenuse.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6f66ddc6b49587', 'les_0beaeb78870f01', 2, 'Find a missing side length of a right triangle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_df887c8760c6d6', 'les_0beaeb78870f01', 3, 'Use the converse to decide whether three lengths form a right triangle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_32dde1d9f2ba0f', 'les_0beaeb78870f01', 4, 'Connect the theorem to the distance formula.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cf75559457d357', 'les_0beaeb78870f01', 'learn', 1, 'definition', '{"term":"Hypotenuse","body":"The side opposite the right angle in a right triangle. It is always the longest side. The other two sides are the legs."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6f66ddc6b49587', 'les_0beaeb78870f01', 'learn', 2, 'formula', '{"latex":"a^2 + b^2 = c^2","title":"The Pythagorean theorem","note":"In any right triangle with legs $a$ and $b$ and hypotenuse $c$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_df887c8760c6d6', 'les_0beaeb78870f01', 'learn', 3, 'text', '{"body":"One classic proof arranges four copies of the right triangle inside a square of side $a + b$. The uncovered region is a tilted square of side $c$, so $(a + b)^2 = 4 \\cdot \\tfrac{1}{2}ab + c^2$. Expanding the left side gives $a^2 + 2ab + b^2 = 2ab + c^2$, and subtracting $2ab$ leaves $a^2 + b^2 = c^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_32dde1d9f2ba0f', 'les_0beaeb78870f01', 'learn', 4, 'worked_example', '{"title":"A ladder 13 ft long leans against a wall with its base 5 ft from the wall. How high does it reach?","steps":[{"latex":"5^2 + b^2 = 13^2","explanation":"The ladder is the hypotenuse; the ground distance is a leg."},{"latex":"25 + b^2 = 169","explanation":"Square the known lengths."},{"latex":"b^2 = 144 \\Rightarrow b = 12","explanation":"Take the positive square root; lengths are positive."}],"check":"$5^2 + 12^2 = 25 + 144 = 169 = 13^2$. The ladder reaches 12 ft up the wall."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ab9f81114516eb', 'les_0beaeb78870f01', 'learn', 5, 'text', '{"body":"The converse is also true: if the side lengths of a triangle satisfy $a^2 + b^2 = c^2$, where $c$ is the longest side, then the triangle is a right triangle. If $a^2 + b^2 > c^2$ the triangle is acute, and if $a^2 + b^2 < c^2$ it is obtuse."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e5c2c8123de43', 'les_0beaeb78870f01', 'learn', 6, 'worked_example', '{"title":"Is a triangle with sides 7, 24 and 25 a right triangle?","steps":[{"latex":"7^2 + 24^2 = 49 + 576 = 625","explanation":"Add the squares of the two shorter sides."},{"latex":"25^2 = 625","explanation":"Square the longest side."},{"latex":"625 = 625","explanation":"They are equal, so by the converse the triangle is right."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ccf39d275e2f18', 'les_0beaeb78870f01', 'learn', 7, 'formula', '{"latex":"d = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}","title":"Distance formula","note":"The horizontal and vertical changes between two points are the legs of a right triangle; the distance is its hypotenuse."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_596085845c847f', 'les_0beaeb78870f01', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"TV and monitor sizes are measured along the diagonal. A screen 48 inches wide and 27 inches tall has a diagonal of $\\sqrt{48^2 + 27^2} = \\sqrt{3033} \\approx 55.1$ inches."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cf75559457d357', 'les_0beaeb78870f01', 1, 'practice', 'numeric', 1, 'A right triangle has legs 6 and 8. How long is the hypotenuse?', '{"answer":10}', '["$c^2 = 6^2 + 8^2$."]', '$c^2 = 36 + 64 = 100$, so $c = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6f66ddc6b49587', 'les_0beaeb78870f01', 2, 'practice', 'numeric', 2, 'A right triangle has hypotenuse 17 and one leg 8. Find the other leg.', '{"answer":15}', '["$8^2 + b^2 = 17^2$."]', '$b^2 = 289 - 64 = 225$, so $b = 15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_df887c8760c6d6', 'les_0beaeb78870f01', 3, 'practice', 'multiple_choice', 2, 'Which side lengths form a right triangle?', '{"choices":["4, 5, 6","5, 12, 13","6, 7, 9","2, 3, 4"],"answer":1}', '["Check whether the two smaller squares add to the largest square."]', '$25 + 144 = 169 = 13^2$. For the others the sums don''t match (e.g. $16 + 25 = 41 \neq 36$).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_32dde1d9f2ba0f', 'les_0beaeb78870f01', 4, 'practice', 'numeric', 2, 'Find the distance between $(1, 2)$ and $(7, 10)$.', '{"answer":10}', '["$\\Delta x = 6$ and $\\Delta y = 8$."]', '$\sqrt{6^2 + 8^2} = \sqrt{100} = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ab9f81114516eb', 'les_0beaeb78870f01', 5, 'practice', 'numeric', 3, 'A square has a diagonal of 10 cm. What is its area in cm²?', '{"answer":50,"unit":"cm²"}', '["If the side is $s$, then $s^2 + s^2 = 10^2$."]', '$2s^2 = 100$, so $s^2 = 50$. The area is $s^2 = 50$ cm².');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8e5c2c8123de43', 'les_0beaeb78870f01', 6, 'review', 'multiple_choice', 3, 'A triangle has sides 8, 9 and 13. Is it acute, right or obtuse?', '{"choices":["Acute","Right","Obtuse","Not a triangle"],"answer":2}', '["Compare $8^2 + 9^2$ with $13^2$."]', '$64 + 81 = 145 < 169$, so the angle opposite the longest side is greater than 90°: obtuse.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ca327f7ab339a1', 'subj_math', 'right-triangles', 'Right triangles', 'Triangles with one 90° angle; their sides satisfy the Pythagorean theorem.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0beaeb78870f01', (SELECT id FROM concepts WHERE slug = 'right-triangles'));
