-- Lesson: quadratic-formula
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d329c5cdfe0fde', 'quadratic-formula', 'The quadratic formula and the discriminant', 'Solve any quadratic equation with the quadratic formula and use the discriminant to predict the number of real solutions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5b1012792f2339', 'les_d329c5cdfe0fde', 1, 'Write a quadratic equation in standard form and identify a, b and c.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3f88cd80fbccf1', 'les_d329c5cdfe0fde', 2, 'Solve quadratic equations using the quadratic formula.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7711deacbec39e', 'les_d329c5cdfe0fde', 3, 'Use the discriminant to determine the number and type of solutions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b1012792f2339', 'les_d329c5cdfe0fde', 'learn', 1, 'text', '{"body":"Factoring is quick when it works, but many quadratics don''t factor nicely over the integers. The quadratic formula solves every equation of the form $ax^2 + bx + c = 0$ with $a \\neq 0$. It comes from completing the square on the general equation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3f88cd80fbccf1', 'les_d329c5cdfe0fde', 'learn', 2, 'formula', '{"latex":"x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}","title":"The quadratic formula","note":"The $\\pm$ produces two solutions: one with $+$ and one with $-$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7711deacbec39e', 'les_d329c5cdfe0fde', 'learn', 3, 'callout', '{"tone":"warning","title":"Standard form first","body":"The equation must equal zero. For $2x^2 = 3x + 5$, rewrite it as $2x^2 - 3x - 5 = 0$ before reading off $a = 2$, $b = -3$, $c = -5$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bc9e9786d81c9c', 'les_d329c5cdfe0fde', 'learn', 4, 'worked_example', '{"title":"Solve $2x^2 - 3x - 5 = 0$","steps":[{"latex":"a = 2,\\ b = -3,\\ c = -5","explanation":"Identify the coefficients, including signs."},{"latex":"x = \\frac{3 \\pm \\sqrt{9 - 4(2)(-5)}}{4}","explanation":"$-b = 3$ and $b^2 = 9$."},{"latex":"x = \\frac{3 \\pm \\sqrt{49}}{4} = \\frac{3 \\pm 7}{4}","explanation":"Simplify under the radical: 9 + 40 = 49."},{"latex":"x = \\frac{10}{4} = \\tfrac{5}{2} \\quad\\text{or}\\quad x = \\frac{-4}{4} = -1","explanation":"Take the + and − cases."}],"check":"$2(\\tfrac{5}{2})^2 - 3(\\tfrac{5}{2}) - 5 = 12.5 - 7.5 - 5 = 0$ and $2(1) + 3 - 5 = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c7f36d278ae16b', 'les_d329c5cdfe0fde', 'learn', 5, 'formula', '{"latex":"\\Delta = b^2 - 4ac","title":"The discriminant","note":"$\\Delta > 0$: two real solutions. $\\Delta = 0$: one repeated real solution. $\\Delta < 0$: no real solutions (two complex ones)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0f268cd6c8dc87', 'les_d329c5cdfe0fde', 'learn', 6, 'text', '{"body":"The discriminant connects algebra to the graph. The solutions of $ax^2 + bx + c = 0$ are the x-intercepts of $y = ax^2 + bx + c$, so the discriminant tells you whether the parabola crosses the x-axis twice, touches it once, or misses it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d1be427201b4b7', 'les_d329c5cdfe0fde', 'learn', 7, 'worked_example', '{"title":"Solve $x^2 + 4x + 1 = 0$ exactly","steps":[{"latex":"x = \\frac{-4 \\pm \\sqrt{16 - 4}}{2}","explanation":"a = 1, b = 4, c = 1."},{"latex":"x = \\frac{-4 \\pm \\sqrt{12}}{2} = \\frac{-4 \\pm 2\\sqrt{3}}{2}","explanation":"$\\sqrt{12} = 2\\sqrt{3}$."},{"latex":"x = -2 \\pm \\sqrt{3}","explanation":"Divide every term by 2."}],"check":"As decimals, $x \\approx -0.268$ and $x \\approx -3.732$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0c30aa6a3ce062', 'les_d329c5cdfe0fde', 'experiment', 8, 'activity', '{"activity":"vertex-explorer","title":"See the discriminant on the graph"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9900b4d21d776f', 'les_d329c5cdfe0fde', 'experiment', 9, 'callout', '{"tone":"tip","title":"Investigate","body":"Make a parabola with two zeros, then slide its vertex until the zeros merge into one. What is $k$ at that moment? Keep going: when the graph no longer reaches the x-axis, the discriminant of the expanded form is negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2240a33564e533', 'les_d329c5cdfe0fde', 'learn', 10, 'callout', '{"tone":"application","title":"Where this shows up","body":"A ball thrown upward from 2 m at 15 m/s has height $h = -4.9t^2 + 15t + 2$. Setting $h = 0$ and using the formula gives $t \\approx 3.19$ s, when it hits the ground; the negative root is discarded because time can''t be negative here."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b1012792f2339', 'les_d329c5cdfe0fde', 1, 'practice', 'numeric', 1, 'What is the discriminant of $x^2 - 6x + 9 = 0$?', '{"answer":0}', '["$b^2 - 4ac$ with $a = 1, b = -6, c = 9$."]', '$36 - 36 = 0$, so there is one repeated solution, $x = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3f88cd80fbccf1', 'les_d329c5cdfe0fde', 2, 'practice', 'multiple_choice', 1, 'How many real solutions does $3x^2 + 2x + 5 = 0$ have?', '{"choices":["0","1","2","3"],"answer":0}', '["Compute the discriminant."]', '$\Delta = 4 - 60 = -56 < 0$, so there are no real solutions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7711deacbec39e', 'les_d329c5cdfe0fde', 3, 'practice', 'numeric', 2, 'Solve $x^2 + 2x - 15 = 0$. Enter the larger solution.', '{"answer":3}', '["$\\Delta = 4 + 60 = 64$."]', '$x = \frac{-2 \pm 8}{2}$, giving $3$ and $-5$. The larger is 3.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bc9e9786d81c9c', 'les_d329c5cdfe0fde', 4, 'practice', 'numeric', 2, 'Solve $2x^2 = 7x - 3$. Enter the smaller solution.', '{"answer":0.5,"tolerance":0.001}', '["First rewrite as 2x² − 7x + 3 = 0."]', '$x = \frac{7 \pm \sqrt{49 - 24}}{4} = \frac{7 \pm 5}{4}$, so $x = 3$ or $x = 0.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c7f36d278ae16b', 'les_d329c5cdfe0fde', 5, 'practice', 'numeric', 3, 'For what value of $k$ does $x^2 + kx + 16 = 0$ have exactly one solution, with $k > 0$?', '{"answer":8}', '["Set the discriminant equal to 0: $k^2 - 64 = 0$."]', '$k^2 = 64$, $k = \pm 8$; the positive value is 8, giving $(x + 4)^2 = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0f268cd6c8dc87', 'les_d329c5cdfe0fde', 6, 'review', 'numeric', 3, 'A ball''s height is $h = -4.9t^2 + 15t + 2$ (meters, seconds). When does it hit the ground? Round to two decimals.', '{"answer":3.19,"tolerance":0.01,"unit":"s"}', '["Set h = 0 and use the quadratic formula with a = −4.9.","Keep the positive time."]', '$t = \frac{-15 \pm \sqrt{225 + 39.2}}{-9.8} = \frac{-15 \pm 16.254}{-9.8}$. The positive root is $t = \frac{-31.254}{-9.8} \approx 3.19$ s.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_21fa51d21dc50e', 'subj_math', 'quadratic-functions', 'Quadratic functions', 'Functions of the form ax² + bx + c whose graphs are parabolas.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d329c5cdfe0fde', (SELECT id FROM concepts WHERE slug = 'quadratic-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d329c5cdfe0fde', (SELECT id FROM formulas WHERE slug = 'quadratic-formula'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d329c5cdfe0fde', (SELECT id FROM formulas WHERE slug = 'discriminant'), 2);

-- Lesson: quadratic-functions-vertex-form
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_85dead2a9c217a', 'quadratic-functions-vertex-form', 'Graphing quadratic functions in vertex form', 'Read the vertex, axis of symmetry and direction of a parabola from y = a(x − h)² + k, and connect it to the graph.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1231c6b22d08bc', 'les_85dead2a9c217a', 1, 'Identify the vertex and axis of symmetry from vertex form.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_82faaa3791e89e', 'les_85dead2a9c217a', 2, 'Describe how a, h and k transform the graph of y = x².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_25106914baf42c', 'les_85dead2a9c217a', 3, 'Find the zeros of a quadratic written in vertex form.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1231c6b22d08bc', 'les_85dead2a9c217a', 'learn', 1, 'text', '{"body":"The graph of $y = x^2$ is a U-shaped curve called a parabola, with its lowest point at the origin. Every quadratic function''s graph is a parabola that has been shifted, stretched or flipped from this one."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_82faaa3791e89e', 'les_85dead2a9c217a', 'learn', 2, 'formula', '{"latex":"y = a(x - h)^2 + k","title":"Vertex form","note":"The vertex is $(h, k)$. The axis of symmetry is the vertical line $x = h$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_25106914baf42c', 'les_85dead2a9c217a', 'learn', 3, 'definition', '{"term":"Vertex","body":"The turning point of a parabola: the minimum point when $a > 0$ and the maximum point when $a < 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8de5db511df453', 'les_85dead2a9c217a', 'learn', 4, 'text', '{"body":"Each parameter has one job. $h$ shifts the graph left or right; note the minus sign in $(x - h)$, so $(x + 3)^2$ means $h = -3$. $k$ shifts it up or down. $a$ flips the graph when negative and makes it narrower when $|a| > 1$ or wider when $0 < |a| < 1$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba971494279275', 'les_85dead2a9c217a', 'learn', 5, 'worked_example', '{"title":"Describe $y = -2(x + 1)^2 + 8$ and find its zeros","steps":[{"latex":"a = -2,\\ h = -1,\\ k = 8","explanation":"Rewrite $(x + 1)$ as $(x - (-1))$."},{"latex":"\\text{vertex } (-1, 8),\\ \\text{axis } x = -1","explanation":"Opens down because a < 0, so the vertex is a maximum."},{"latex":"0 = -2(x + 1)^2 + 8","explanation":"Zeros are where y = 0."},{"latex":"(x + 1)^2 = 4","explanation":"Subtract 8, then divide by −2."},{"latex":"x + 1 = \\pm 2 \\Rightarrow x = 1 \\text{ or } x = -3","explanation":"Take square roots: both signs."}],"check":"$-2(2)^2 + 8 = 0$ and $-2(-2)^2 + 8 = 0$. The zeros are symmetric about $x = -1$, as they must be."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97c9669c6b1eda', 'les_85dead2a9c217a', 'learn', 6, 'callout', '{"tone":"note","title":"When are there no real zeros?","body":"If the parabola opens up ($a > 0$) and its vertex is above the x-axis ($k > 0$), it never reaches $y = 0$. In general there are real zeros exactly when $-\\frac{k}{a} \\ge 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_27e5c96074f622', 'les_85dead2a9c217a', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"A ball''s height might be modeled by $h = -4.9(t - 1.5)^2 + 12$ meters. The vertex says it reaches its highest point, 12 m, at $t = 1.5$ s."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_45adfa22ff84de', 'les_85dead2a9c217a', 'experiment', 8, 'activity', '{"activity":"vertex-explorer","title":"Move the vertex"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ecd35bd3dba77e', 'les_85dead2a9c217a', 'experiment', 9, 'callout', '{"tone":"tip","title":"Investigate","body":"Make the zeros $x = 0$ and $x = 4$. Where must the vertex be? Try it with $a = 1$, then with $a = -1$. What has to change about $k$?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_86f1a3845dac36', 'les_85dead2a9c217a', 'watch', 10, 'activity', '{"activity":"vertex-explorer","title":"Walkthrough: from y = x² to any parabola","steps":[{"title":"The parent graph","body":"y = x² has its vertex at the origin and opens up.","params":{"a":1,"h":0,"k":0}},{"title":"Shift right","body":"Replacing x with (x − 2) moves every point 2 units right: the vertex is now (2, 0).","params":{"a":1,"h":2,"k":0}},{"title":"Shift down","body":"Subtracting 3 moves the graph down: vertex (2, −3). It now crosses the x-axis twice.","params":{"a":1,"h":2,"k":-3}},{"title":"Flip and stretch","body":"a = −2 flips it upside down and makes it narrower. The vertex is now a maximum.","params":{"a":-2,"h":2,"k":3}}]}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1231c6b22d08bc', 'les_85dead2a9c217a', 1, 'practice', 'short_text', 1, 'What is the vertex of $y = 3(x - 4)^2 - 5$? Enter it as (h, k).', '{"accept":["(4,-5)"]}', '["Compare with $a(x - h)^2 + k$."]', '$h = 4$ and $k = -5$, so the vertex is $(4, -5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_82faaa3791e89e', 'les_85dead2a9c217a', 2, 'practice', 'multiple_choice', 1, 'Which parabola opens downward and is wider than $y = x^2$?', '{"choices":["$y = 2x^2$","$y = -2x^2$","$y = -\\tfrac{1}{2}x^2$","$y = \\tfrac{1}{2}x^2$"],"answer":2}', '["Downward needs a < 0. Wider needs |a| < 1."]', '$a = -\tfrac{1}{2}$ is negative (opens down) and $|a| < 1$ (wider).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_25106914baf42c', 'les_85dead2a9c217a', 3, 'practice', 'short_text', 2, 'What is the vertex of $y = (x + 6)^2 + 1$? Enter it as (h, k).', '{"accept":["(-6,1)"]}', '["$(x + 6) = (x - (-6))$."]', '$h = -6$, $k = 1$: vertex $(-6, 1)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8de5db511df453', 'les_85dead2a9c217a', 4, 'practice', 'numeric', 2, 'Find the larger zero of $y = (x - 3)^2 - 16$.', '{"answer":7}', '["Solve $(x - 3)^2 = 16$."]', '$x - 3 = \pm 4$, so $x = 7$ or $x = -1$. The larger is 7.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ba971494279275', 'les_85dead2a9c217a', 5, 'practice', 'multiple_choice', 2, 'How many real zeros does $y = 2(x + 1)^2 + 3$ have?', '{"choices":["0","1","2","Infinitely many"],"answer":0}', '["Which way does it open, and where is the vertex?"]', 'It opens up ($a = 2 > 0$) and its lowest point is $(-1, 3)$, above the x-axis, so it never reaches $y = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97c9669c6b1eda', 'les_85dead2a9c217a', 6, 'review', 'numeric', 3, 'A parabola has vertex $(2, -8)$ and passes through $(4, 0)$. Find $a$ in $y = a(x - h)^2 + k$.', '{"answer":2}', '["Substitute the point into $y = a(x - 2)^2 - 8$."]', '$0 = a(2)^2 - 8 \Rightarrow 4a = 8 \Rightarrow a = 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_21fa51d21dc50e', 'subj_math', 'quadratic-functions', 'Quadratic functions', 'Functions of the form ax² + bx + c whose graphs are parabolas.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_85dead2a9c217a', (SELECT id FROM concepts WHERE slug = 'quadratic-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_85dead2a9c217a', (SELECT id FROM formulas WHERE slug = 'vertex-form'), 1);

-- Lesson: riemann-sums
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7ae76dbb5e4056', 'riemann-sums', 'Approximating areas with Riemann sums', 'Estimate the area under a curve with rectangles and trapezoids, judge over- and underestimates, and see the sums converge to the integral.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9f40ad8bb4d764', 'les_7ae76dbb5e4056', 1, 'Compute left, right and midpoint Riemann sums and the trapezoidal sum.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a42056569e6006', 'les_7ae76dbb5e4056', 2, 'Decide whether a sum over- or underestimates using monotonicity or concavity.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aaee3d6ca173ff', 'les_7ae76dbb5e4056', 3, 'Explain how Riemann sums lead to the definite integral.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f40ad8bb4d764', 'les_7ae76dbb5e4056', 'learn', 1, 'text', '{"body":"If a car''s velocity were constant, distance would be velocity times time: the area of a rectangle under the velocity graph. When velocity changes, we can slice time into short pieces, treat velocity as nearly constant on each, and add up the rectangles. That sum is a Riemann sum."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a42056569e6006', 'les_7ae76dbb5e4056', 'learn', 2, 'definition', '{"term":"Riemann sum","body":"For $f$ on $[a, b]$ split into $n$ equal subintervals of width $\\Delta x = \\frac{b - a}{n}$, the sum $\\sum f(x_i^*)\\Delta x$, where $x_i^*$ is a chosen point in each subinterval: its left end, right end or midpoint."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aaee3d6ca173ff', 'les_7ae76dbb5e4056', 'learn', 3, 'worked_example', '{"title":"Estimate $\\int_0^2 x^2\\,dx$ with a left sum, $n = 4$","steps":[{"latex":"\\Delta x = \\frac{2 - 0}{4} = 0.5","explanation":"Four subintervals of width 0.5."},{"latex":"x = 0,\\ 0.5,\\ 1,\\ 1.5","explanation":"Left endpoints."},{"latex":"0.5\\,(0 + 0.25 + 1 + 2.25)","explanation":"Heights f(x) = x²."},{"latex":"= 0.5(3.5) = 1.75","explanation":"Left sum."}],"check":"The right sum uses $x = 0.5, 1, 1.5, 2$: $0.5(0.25 + 1 + 2.25 + 4) = 3.75$. The exact value is $\\frac{8}{3} \\approx 2.667$, between them."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b76767b2c7504', 'les_7ae76dbb5e4056', 'learn', 4, 'callout', '{"tone":"tip","title":"Over or under?","body":"For an increasing function, left sums underestimate and right sums overestimate. For a concave-up function, the trapezoidal sum overestimates and the midpoint sum underestimates; concave down reverses both."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e2aed4ceb6c2c3', 'les_7ae76dbb5e4056', 'learn', 5, 'formula', '{"latex":"T = \\frac{\\Delta x}{2}\\big[f(x_0) + 2f(x_1) + \\cdots + 2f(x_{n-1}) + f(x_n)\\big]","title":"Trapezoidal sum","note":"Equal to the average of the left and right sums."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5fdeec9be9cbce', 'les_7ae76dbb5e4056', 'learn', 6, 'text', '{"body":"As $n$ grows, every one of these sums approaches the same number for a continuous function. That limit is the definite integral $\\int_a^b f(x)\\,dx$, the net signed area between the graph and the x-axis: area above the axis counts as positive and area below as negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_31013148e28631', 'les_7ae76dbb5e4056', 'learn', 7, 'callout', '{"tone":"note","title":"Connection to antiderivatives","body":"The Fundamental Theorem of Calculus says this limit can be computed exactly with an antiderivative: $\\int_0^2 x^2\\,dx = \\frac{2^3}{3} - 0 = \\frac{8}{3}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_087e86cb16d5cb', 'les_7ae76dbb5e4056', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers estimate fuel used from a flow-rate log sampled once a minute: that''s a Riemann sum with $\\Delta x = 1$ minute. Doctors estimate total drug exposure as the area under a concentration-time curve the same way."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_63f873f8666115', 'les_7ae76dbb5e4056', 'experiment', 9, 'activity', '{"activity":"riemann-sum","title":"Compare the sums","params":{"fn":"x^2"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd7935b87e3876', 'les_7ae76dbb5e4056', 'experiment', 10, 'callout', '{"tone":"tip","title":"Investigate","body":"For $f(x) = x^2$ on $[0, 2]$, how large must $n$ be before the left sum is within 0.01 of $\\frac{8}{3}$? How large for the midpoint sum? What does that suggest about which method is more efficient?"}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9f40ad8bb4d764', 'les_7ae76dbb5e4056', 1, 'practice', 'numeric', 1, 'Compute the right Riemann sum for $f(x) = 2x$ on $[0, 3]$ with $n = 3$.', '{"answer":12}', '["$\\Delta x = 1$; right endpoints 1, 2, 3."]', '$1 \cdot (2 + 4 + 6) = 12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a42056569e6006', 'les_7ae76dbb5e4056', 2, 'practice', 'numeric', 2, 'Compute the midpoint sum for $f(x) = x^2$ on $[0, 2]$ with $n = 2$.', '{"answer":2.5,"tolerance":0.0001}', '["Midpoints are 0.5 and 1.5; $\\Delta x = 1$."]', '$1 \cdot (0.25 + 2.25) = 2.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aaee3d6ca173ff', 'les_7ae76dbb5e4056', 3, 'practice', 'multiple_choice', 2, '$f$ is increasing on $[a, b]$. Which is true?', '{"choices":["Left sum ≥ integral","Left sum ≤ integral ≤ right sum","Right sum ≤ integral","The sums are equal"],"answer":1}', '["On each subinterval, where is f smallest?"]', 'An increasing function is lowest at the left of each subinterval, so left sums underestimate and right sums overestimate.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b76767b2c7504', 'les_7ae76dbb5e4056', 4, 'practice', 'numeric', 2, 'Compute the trapezoidal sum for $f(x) = x^2$ on $[0, 2]$ with $n = 4$.', '{"answer":2.75,"tolerance":0.0001}', '["It''s the average of the left sum (1.75) and the right sum (3.75)."]', '$\frac{1.75 + 3.75}{2} = 2.75$, an overestimate because $x^2$ is concave up.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e2aed4ceb6c2c3', 'les_7ae76dbb5e4056', 5, 'review', 'numeric', 3, 'Use the Fundamental Theorem to evaluate $\int_1^3 (2x + 1)\,dx$.', '{"answer":10}', '["An antiderivative is $F(x) = x^2 + x$."]', '$F(3) - F(1) = 12 - 2 = 10$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_036004a8a66e16', 'subj_math', 'definite-integral', 'Definite integral', 'The limit of Riemann sums; the net signed area between a curve and the x-axis.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7ae76dbb5e4056', (SELECT id FROM concepts WHERE slug = 'definite-integral'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7ae76dbb5e4056', (SELECT id FROM formulas WHERE slug = 'riemann-sum'), 1);
