-- Lesson: secant-to-tangent
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1ef9532f3f83f8', 'secant-to-tangent', 'From average to instantaneous rate of change', 'Approximate the slope of a curve at a point with secant lines and see how the limit of their slopes defines the derivative.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cad4dc260b6273', 'les_1ef9532f3f83f8', 1, 'Compute the average rate of change of a function on an interval.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f904347649a254', 'les_1ef9532f3f83f8', 2, 'Estimate an instantaneous rate of change using shrinking intervals.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3877fef39677ac', 'les_1ef9532f3f83f8', 3, 'Interpret the derivative as the limit of secant slopes and as the slope of the tangent line.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cad4dc260b6273', 'les_1ef9532f3f83f8', 'learn', 1, 'text', '{"body":"A car''s speedometer reads 50 mph at one instant. But speed is distance divided by time, and at a single instant no time passes and no distance is covered. This puzzle, how change can happen at an instant, is the starting point of calculus."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f904347649a254', 'les_1ef9532f3f83f8', 'learn', 2, 'definition', '{"term":"Average rate of change","body":"For $f$ on $[a, b]$, the change in output divided by the change in input: $\\frac{f(b) - f(a)}{b - a}$. It is the slope of the secant line through $(a, f(a))$ and $(b, f(b))$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3877fef39677ac', 'les_1ef9532f3f83f8', 'learn', 3, 'worked_example', '{"title":"Average rate of change of $f(x) = x^2$ on $[1, 3]$","steps":[{"latex":"\\frac{f(3) - f(1)}{3 - 1} = \\frac{9 - 1}{2}","explanation":"Evaluate at the endpoints."},{"latex":"= 4","explanation":"On average, f increases 4 units per unit of x on this interval."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_24b42407fb0a74', 'les_1ef9532f3f83f8', 'learn', 4, 'text', '{"body":"To find the rate at exactly $x = 1$, use intervals $[1, 1 + h]$ with smaller and smaller $h$. For $f(x) = x^2$ the secant slope is $\\frac{(1 + h)^2 - 1}{h} = \\frac{2h + h^2}{h} = 2 + h$. With $h = 0.1$ it''s 2.1; with $h = 0.01$ it''s 2.01; with $h = 0.001$ it''s 2.001. The slopes approach 2."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8a0154456a1196', 'les_1ef9532f3f83f8', 'learn', 5, 'formula', '{"latex":"f''(a) = \\lim_{h \\to 0} \\frac{f(a + h) - f(a)}{h}","title":"The derivative at a point","note":"When this limit exists, $f''(a)$ is the instantaneous rate of change at $a$ and the slope of the tangent line there."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3774b7373514d3', 'les_1ef9532f3f83f8', 'learn', 6, 'worked_example', '{"title":"Use the definition to find $f''(3)$ for $f(x) = x^2$","steps":[{"latex":"\\frac{(3 + h)^2 - 9}{h} = \\frac{9 + 6h + h^2 - 9}{h}","explanation":"Expand."},{"latex":"= \\frac{6h + h^2}{h} = 6 + h \\quad (h \\neq 0)","explanation":"Factor out h and cancel; h is never exactly 0 in the limit."},{"latex":"f''(3) = \\lim_{h \\to 0}(6 + h) = 6","explanation":"Now let h approach 0."}],"check":"This matches the pattern $f''(x) = 2x$ for $f(x) = x^2$, which the power rule gives directly."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0603d029e68b1', 'les_1ef9532f3f83f8', 'learn', 7, 'callout', '{"tone":"note","title":"Tangent line","body":"The tangent line to $y = f(x)$ at $x = a$ is $y = f(a) + f''(a)(x - a)$. Near $a$ it is the best straight-line approximation of the curve."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b414cc1f9a6bc5', 'les_1ef9532f3f83f8', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"If $s(t) = 4.9t^2$ is the distance in meters a dropped object has fallen after $t$ seconds, then $s''(2) = 9.8 \\cdot 2 = 19.6$ m/s is its speed at exactly 2 seconds."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7865a4c1c580bd', 'les_1ef9532f3f83f8', 'experiment', 9, 'activity', '{"activity":"tangent-line","title":"Shrink the interval","params":{"fn":"x^2"}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fcc05bb2ce8a70', 'les_1ef9532f3f83f8', 'experiment', 10, 'callout', '{"tone":"tip","title":"Investigate","body":"With $f(x) = x^3$ at $a = 1$, record the secant slope for $h = 1, 0.5, 0.1, 0.01$. What value do they approach? Try a negative $h$: do the slopes approach the same number from the other side?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_04f439465488bd', 'les_1ef9532f3f83f8', 'watch', 11, 'activity', '{"activity":"tangent-line","title":"Walkthrough: secant slopes approach the tangent slope","steps":[{"title":"A wide secant","body":"With h = 2 on f(x) = x² at a = 1, the secant slope is 4.","params":{"fn":"x^2","a":1,"h":2}},{"title":"Narrower","body":"h = 1 gives slope 3; h = 0.5 gives 2.5.","params":{"fn":"x^2","a":1,"h":0.5}},{"title":"Very close","body":"h = 0.05 gives 2.05. The secant is almost indistinguishable from the tangent.","params":{"fn":"x^2","a":1,"h":0.05}},{"title":"The limit","body":"As h → 0 the slopes approach 2 = f′(1).","params":{"fn":"x^2","a":1,"h":0.01}}]}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cad4dc260b6273', 'les_1ef9532f3f83f8', 1, 'practice', 'numeric', 1, 'Find the average rate of change of $f(x) = 3x^2$ on $[0, 2]$.', '{"answer":6}', '["$\\frac{f(2) - f(0)}{2 - 0}$."]', '$\frac{12 - 0}{2} = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f904347649a254', 'les_1ef9532f3f83f8', 2, 'practice', 'numeric', 2, 'For $f(x) = x^2$, what is the slope of the secant line from $x = 2$ to $x = 2.1$?', '{"answer":4.1,"tolerance":0.0001}', '["$\\frac{2.1^2 - 2^2}{0.1}$."]', '$\frac{4.41 - 4}{0.1} = 4.1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3877fef39677ac', 'les_1ef9532f3f83f8', 3, 'practice', 'numeric', 2, 'Use the limit definition to find $f''(1)$ for $f(x) = x^2 + 3x$.', '{"answer":5}', '["Compute $\\frac{f(1 + h) - f(1)}{h}$ and simplify before letting $h \\to 0$."]', '$\frac{(1 + h)^2 + 3(1 + h) - 4}{h} = \frac{5h + h^2}{h} = 5 + h \to 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_24b42407fb0a74', 'les_1ef9532f3f83f8', 4, 'practice', 'multiple_choice', 2, '$f''(a)$ represents all of the following except:', '{"choices":["The slope of the tangent line at x = a","The instantaneous rate of change of f at a","The limit of secant slopes as h → 0","The average rate of change of f on [0, a]"],"answer":3}', '["Which one uses a whole interval?"]', 'The average rate on $[0, a]$ is a secant slope over a fixed interval, not the derivative at $a$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8a0154456a1196', 'les_1ef9532f3f83f8', 5, 'review', 'numeric', 3, 'Write the tangent line to $f(x) = x^2$ at $x = 3$ as $y = mx + b$. Enter $b$.', '{"answer":-9}', '["$f(3) = 9$ and $f''(3) = 6$.","$y = 9 + 6(x - 3)$."]', '$y = 9 + 6x - 18 = 6x - 9$, so $b = -9$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1c8ac8d97a42f7', 'subj_math', 'derivative', 'Derivative', 'The instantaneous rate of change of a function; the limit of secant slopes.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1ef9532f3f83f8', (SELECT id FROM concepts WHERE slug = 'derivative'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9523ccbcc4c521', 'subj_math', 'limits', 'Limits', 'The value a function''s output approaches as its input approaches a given value.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1ef9532f3f83f8', (SELECT id FROM concepts WHERE slug = 'limits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1ef9532f3f83f8', (SELECT id FROM formulas WHERE slug = 'derivative-definition'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_1ef9532f3f83f8', (SELECT id FROM formulas WHERE slug = 'power-rule'), 2);

-- Lesson: series-parallel-circuits
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_984e0c77b50507', 'series-parallel-circuits', 'Series and parallel circuits', 'Use Ohm''s law and conservation of charge and energy to find current, voltage and power in series and parallel resistor circuits.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0aa03508ed2300', 'les_984e0c77b50507', 1, 'Apply Ohm''s law to a resistor.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_62ff4ff4a875e1', 'les_984e0c77b50507', 2, 'Find the equivalent resistance of resistors in series and in parallel.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d17ef41b0a71cb', 'les_984e0c77b50507', 3, 'Determine the current through and voltage across each resistor.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3adb59ec2b71ea', 'les_984e0c77b50507', 4, 'Calculate power dissipated in circuit elements.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0aa03508ed2300', 'les_984e0c77b50507', 'learn', 1, 'definition', '{"term":"Current","body":"The rate at which charge flows past a point, $I = \\frac{\\Delta q}{\\Delta t}$, measured in amperes (A)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_62ff4ff4a875e1', 'les_984e0c77b50507', 'learn', 2, 'definition', '{"term":"Potential difference (voltage)","body":"Energy per unit charge transferred between two points, measured in volts (V = J/C). A battery raises the potential; resistors lower it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d17ef41b0a71cb', 'les_984e0c77b50507', 'learn', 3, 'formula', '{"latex":"V = IR","title":"Ohm''s law","note":"Holds for ohmic resistors at constant temperature."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3adb59ec2b71ea', 'les_984e0c77b50507', 'learn', 4, 'text', '{"body":"In series, components share one path, so the same current flows through each. Their voltages add to the battery''s voltage, because energy per charge is conserved around the loop. In parallel, components sit on separate branches between the same two points, so each has the same voltage, and the branch currents add to the total, because charge is conserved at the junction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f4f4b31ece580a', 'les_984e0c77b50507', 'learn', 5, 'formula', '{"latex":"R_s = R_1 + R_2, \\qquad \\frac{1}{R_p} = \\frac{1}{R_1} + \\frac{1}{R_2}","title":"Equivalent resistance","note":"A parallel combination is always smaller than its smallest resistor: adding a branch gives current another path."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3393a47fd9e67c', 'les_984e0c77b50507', 'learn', 6, 'worked_example', '{"title":"A 12 V battery drives a 4 Ω and an 8 Ω resistor in series.","steps":[{"latex":"R_s = 4 + 8 = 12\\ \\Omega","explanation":"Series resistances add."},{"latex":"I = \\frac{12}{12} = 1.0\\ \\text{A}","explanation":"The same current through both."},{"latex":"V_1 = 1.0(4) = 4\\ \\text{V},\\quad V_2 = 1.0(8) = 8\\ \\text{V}","explanation":"The voltages add to 12 V."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5823694bd18f86', 'les_984e0c77b50507', 'learn', 7, 'worked_example', '{"title":"The same resistors in parallel across 12 V.","steps":[{"latex":"\\frac{1}{R_p} = \\frac{1}{4} + \\frac{1}{8} = \\frac{3}{8} \\Rightarrow R_p \\approx 2.67\\ \\Omega","explanation":"Reciprocals add."},{"latex":"I_1 = \\frac{12}{4} = 3\\ \\text{A},\\quad I_2 = \\frac{12}{8} = 1.5\\ \\text{A}","explanation":"Each branch has the full 12 V."},{"latex":"I_{\\text{total}} = 4.5\\ \\text{A} = \\frac{12}{2.67}","explanation":"Branch currents add, matching V/R_p."}],"check":"Power from the battery is $P = IV = 4.5 \\times 12 = 54$ W in parallel, versus $12$ W in series: parallel loads draw more power."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b55fc403a98df5', 'les_984e0c77b50507', 'learn', 8, 'callout', '{"tone":"warning","title":"Model limits","body":"The simulator treats the battery and wires as ideal (no internal resistance) and the resistors as ohmic. Real batteries'' terminal voltage drops as current increases, and bulbs'' resistance rises as they heat up."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0c94c1e1aeccd5', 'les_984e0c77b50507', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Household outlets are wired in parallel so each device gets the full voltage and one switch doesn''t turn off the whole house. Old holiday lights were wired in series, which is why one dead bulb darkened the whole string."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4fb8de27f3455a', 'les_984e0c77b50507', 'experiment', 10, 'activity', '{"activity":"circuit-builder","title":"Series or parallel?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e942e326797d1', 'les_984e0c77b50507', 'experiment', 11, 'callout', '{"tone":"tip","title":"Investigate","body":"With a 9 V battery, set $R_1 = R_2 = 10\\ \\Omega$. Compare total current in series and in parallel. Now make $R_2$ huge (100 Ω): what happens to the parallel equivalent resistance, and why?"}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0aa03508ed2300', 'les_984e0c77b50507', 1, 'practice', 'numeric', 1, 'What current flows through a 6 Ω resistor with 18 V across it?', '{"answer":3,"unit":"A"}', '["$I = V/R$."]', '$18 / 6 = 3$ A.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_62ff4ff4a875e1', 'les_984e0c77b50507', 2, 'practice', 'numeric', 1, 'Find the equivalent resistance of 3 Ω, 5 Ω and 7 Ω in series.', '{"answer":15,"unit":"Ω"}', '["Series resistances add."]', '$3 + 5 + 7 = 15\ \Omega$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d17ef41b0a71cb', 'les_984e0c77b50507', 3, 'practice', 'numeric', 2, 'Find the equivalent resistance of 6 Ω and 3 Ω in parallel.', '{"answer":2,"unit":"Ω"}', '["$\\frac{1}{R_p} = \\frac{1}{6} + \\frac{1}{3}$."]', '$\frac{1}{6} + \frac{2}{6} = \frac{3}{6}$, so $R_p = 2\ \Omega$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3adb59ec2b71ea', 'les_984e0c77b50507', 4, 'practice', 'multiple_choice', 2, 'Two identical bulbs in parallel are connected to a battery. One burns out. The other bulb:', '{"choices":["Goes out","Gets dimmer","Stays the same brightness","Gets brighter"],"answer":2}', '["What is the voltage across each parallel branch?"]', 'Each branch still has the full battery voltage (ideal battery), so the remaining bulb''s current and brightness don''t change.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f4f4b31ece580a', 'les_984e0c77b50507', 5, 'practice', 'numeric', 2, 'A 10 Ω and a 15 Ω resistor are in series across 20 V. What is the voltage across the 15 Ω resistor?', '{"answer":12,"unit":"V"}', '["Find the current first: I = 20/25."]', '$I = 0.8$ A, so $V = 0.8 \times 15 = 12$ V.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3393a47fd9e67c', 'les_984e0c77b50507', 6, 'review', 'numeric', 3, 'A 120 V outlet powers a 60 W lamp and a 1200 W heater in parallel. What total current is drawn?', '{"answer":10.5,"tolerance":0.01,"unit":"A"}', '["$I = P/V$ for each device."]', '$0.5 + 10 = 10.5$ A.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_219b9bd8420acd', 'subj_phys', 'electric-circuits', 'Electric circuits', 'Closed paths through which charge flows, driven by a potential difference.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_984e0c77b50507', (SELECT id FROM concepts WHERE slug = 'electric-circuits'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_66bdfe1d6261ba', 'subj_phys', 'ohms-law', 'Ohm''s law', 'For ohmic resistors, voltage is proportional to current.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_984e0c77b50507', (SELECT id FROM concepts WHERE slug = 'ohms-law'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_984e0c77b50507', (SELECT id FROM formulas WHERE slug = 'ohms-law'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_984e0c77b50507', (SELECT id FROM formulas WHERE slug = 'resistors-series-parallel'), 2);
