-- Lesson: simple-harmonic-motion
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2d06d139530b97', 'simple-harmonic-motion', 'Simple harmonic motion', 'Model a mass on a spring: restoring force, period, and the exchange of kinetic and elastic potential energy.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3e1250c9dda336', 'les_2d06d139530b97', 1, 'Identify simple harmonic motion from a linear restoring force.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_189fc538f5237d', 'les_2d06d139530b97', 2, 'Calculate period and frequency of a mass-spring system.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5793191f7b5a86', 'les_2d06d139530b97', 3, 'Track kinetic and potential energy through an oscillation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e1250c9dda336', 'les_2d06d139530b97', 'learn', 1, 'formula', '{"latex":"F_s = -kx","title":"Hooke''s law","note":"An ideal spring pulls back toward equilibrium with a force proportional to the stretch $x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_189fc538f5237d', 'les_2d06d139530b97', 'learn', 2, 'definition', '{"term":"Simple harmonic motion (SHM)","body":"Motion in which the restoring force is proportional to displacement and opposite to it. The position follows a sine or cosine curve in time: $x(t) = A\\cos(2\\pi t / T)$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5793191f7b5a86', 'les_2d06d139530b97', 'learn', 3, 'text', '{"body":"Three numbers describe the motion. The amplitude $A$ is the maximum displacement. The period $T$ is the time for one full cycle, and the frequency $f = \\frac{1}{T}$ is cycles per second, measured in hertz."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_69d882dbd2766d', 'les_2d06d139530b97', 'learn', 4, 'formula', '{"latex":"T = 2\\pi\\sqrt{\\frac{m}{k}}","title":"Period of a mass on a spring","note":"A heavier mass oscillates more slowly; a stiffer spring oscillates faster. Amplitude does not appear: for an ideal spring, big and small oscillations take the same time."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f7e863f7da807c', 'les_2d06d139530b97', 'learn', 5, 'worked_example', '{"title":"A 0.50 kg mass hangs on a spring with $k = 200$ N/m. Find the period and frequency.","steps":[{"latex":"T = 2\\pi\\sqrt{\\frac{0.50}{200}} = 2\\pi(0.05)","explanation":"Substitute."},{"latex":"T \\approx 0.314\\ \\text{s}","explanation":"One full oscillation."},{"latex":"f = \\frac{1}{T} \\approx 3.18\\ \\text{Hz}","explanation":"About 3 oscillations per second."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cf8e5ed2095d48', 'les_2d06d139530b97', 'learn', 6, 'text', '{"body":"Energy moves back and forth between two forms. At the turning points ($x = \\pm A$) the mass stops for an instant, so all the energy is elastic potential energy $\\tfrac{1}{2}kA^2$. At equilibrium ($x = 0$) the spring is relaxed and all the energy is kinetic, so the speed is greatest there."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_001f50c7a43069', 'les_2d06d139530b97', 'learn', 7, 'worked_example', '{"title":"For that system pulled 0.10 m and released, find the maximum speed.","steps":[{"latex":"E = \\tfrac{1}{2}kA^2 = \\tfrac{1}{2}(200)(0.10)^2 = 1.0\\ \\text{J}","explanation":"Total energy at the turning point."},{"latex":"\\tfrac{1}{2}mv_{\\max}^2 = 1.0 \\Rightarrow v_{\\max}^2 = \\frac{2(1.0)}{0.50} = 4","explanation":"All kinetic at equilibrium."},{"latex":"v_{\\max} = 2.0\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9ff1931fedf666', 'les_2d06d139530b97', 'learn', 8, 'callout', '{"tone":"warning","title":"Model limits","body":"Real springs lose energy to friction and air, so the amplitude slowly decreases (damping). Very large stretches can also go beyond the spring''s linear range. The simulator models an ideal, undamped spring unless you turn damping on."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d4f6dac1fafa0', 'les_2d06d139530b97', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car suspensions, building sway in earthquakes, quartz watch crystals and the vibration of molecules are all modeled as harmonic oscillators."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0e0e7e47560974', 'les_2d06d139530b97', 'experiment', 10, 'activity', '{"activity":"spring-oscillator","title":"Mass on a spring"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fd68a06c2bfd80', 'les_2d06d139530b97', 'experiment', 11, 'callout', '{"tone":"tip","title":"Investigate","body":"Double the amplitude. Does the period change? Now quadruple the mass: by what factor does the period change? Turn on damping and watch the energy bars."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b4bcc11ff692a9', 'les_2d06d139530b97', 'watch', 12, 'activity', '{"activity":"spring-oscillator","title":"Walkthrough: energy in an oscillator","steps":[{"title":"Pull and release","body":"At maximum stretch the mass is momentarily at rest: all potential energy.","params":{"mass":0.5,"k":20,"amplitude":0.3}},{"title":"Heavier mass","body":"Four times the mass doubles the period: T ∝ √m.","params":{"mass":2,"k":20,"amplitude":0.3}},{"title":"Stiffer spring","body":"A spring four times stiffer halves the period.","params":{"mass":0.5,"k":80,"amplitude":0.3}}]}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3e1250c9dda336', 'les_2d06d139530b97', 1, 'practice', 'numeric', 1, 'A spring with $k = 50$ N/m is stretched 0.20 m. What is the magnitude of the restoring force?', '{"answer":10,"unit":"N"}', '["$|F| = kx$."]', '$50 \times 0.20 = 10$ N.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_189fc538f5237d', 'les_2d06d139530b97', 2, 'practice', 'numeric', 2, 'Find the period of a 2.0 kg mass on a spring with $k = 80$ N/m. Round to two decimals.', '{"answer":0.99,"tolerance":0.01,"unit":"s"}', '["$T = 2\\pi\\sqrt{m/k}$."]', '$2\pi\sqrt{0.025} \approx 2\pi(0.158) \approx 0.99$ s.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5793191f7b5a86', 'les_2d06d139530b97', 3, 'practice', 'multiple_choice', 2, 'The mass on a spring is replaced by one 4 times heavier. The period becomes:', '{"choices":["4 times longer","2 times longer","Half as long","Unchanged"],"answer":1}', '["$T \\propto \\sqrt{m}$."]', '$\sqrt{4} = 2$, so the period doubles.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_69d882dbd2766d', 'les_2d06d139530b97', 4, 'practice', 'multiple_choice', 2, 'Where is the speed of an oscillating mass greatest?', '{"choices":["At maximum stretch","At maximum compression","At equilibrium","Speed is constant"],"answer":2}', '["Where is the potential energy smallest?"]', 'At equilibrium the spring stores no energy, so all of it is kinetic and the speed is maximum.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f7e863f7da807c', 'les_2d06d139530b97', 5, 'review', 'numeric', 3, 'A 0.25 kg mass on a spring ($k = 100$ N/m) oscillates with amplitude 0.05 m. What is its maximum speed?', '{"answer":1,"tolerance":0.001,"unit":"m/s"}', '["$\\tfrac{1}{2}kA^2 = \\tfrac{1}{2}mv^2$."]', '$v = A\sqrt{k/m} = 0.05\sqrt{400} = 1.0$ m/s.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_2d06d139530b97', 'subj_phys', 'simple-harmonic-motion', 'Simple harmonic motion', 'Periodic motion produced by a restoring force proportional to displacement.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2d06d139530b97', (SELECT id FROM concepts WHERE slug = 'simple-harmonic-motion'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_77cf4022b7587a', 'subj_phys', 'conservation-of-energy', 'Conservation of energy', 'In a closed system without dissipation, total mechanical energy stays constant.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2d06d139530b97', (SELECT id FROM concepts WHERE slug = 'conservation-of-energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_2d06d139530b97', (SELECT id FROM formulas WHERE slug = 'hookes-law'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_2d06d139530b97', (SELECT id FROM formulas WHERE slug = 'spring-period'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_2d06d139530b97', (SELECT id FROM formulas WHERE slug = 'kinetic-energy'), 3);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_2d06d139530b97', (SELECT id FROM formulas WHERE slug = 'spring-potential-energy'), 4);

-- Lesson: slope-and-rate-of-change
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_99b46ef0609ea1', 'slope-and-rate-of-change', 'Slope and rate of change', 'Measure how steep a line is as rise over run, find slope from two points, and interpret it as a rate of change.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c5a547ff4f539d', 'les_99b46ef0609ea1', 1, 'Find the slope of a line from a graph, a table or two points.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4434e32cdcbdc2', 'les_99b46ef0609ea1', 2, 'Interpret slope as a rate of change with units.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_12196efeea09b8', 'les_99b46ef0609ea1', 3, 'Describe lines with positive, negative, zero and undefined slope.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c5a547ff4f539d', 'les_99b46ef0609ea1', 'learn', 1, 'text', '{"body":"Slope measures how much $y$ changes for each one-unit change in $x$. On a graph that is the steepness of the line: how far it rises (or falls) as you move one step to the right."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4434e32cdcbdc2', 'les_99b46ef0609ea1', 'learn', 2, 'definition', '{"term":"Slope","body":"For two points $(x_1, y_1)$ and $(x_2, y_2)$ on a non-vertical line, the slope is the change in $y$ divided by the change in $x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_12196efeea09b8', 'les_99b46ef0609ea1', 'learn', 3, 'formula', '{"latex":"m = \\frac{\\Delta y}{\\Delta x} = \\frac{y_2 - y_1}{x_2 - x_1}","title":"Slope formula","note":"$\\Delta$ (delta) means \"change in\". The two points can be taken in either order, as long as you use the same order on top and bottom."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4184fc4a7bf6f0', 'les_99b46ef0609ea1', 'learn', 4, 'worked_example', '{"title":"Find the slope through $(1, 3)$ and $(4, 9)$","steps":[{"latex":"m = \\frac{9 - 3}{4 - 1}","explanation":"Subtract the y-values and the x-values in the same order."},{"latex":"m = \\frac{6}{3} = 2","explanation":"y rises 2 units for every 1 unit to the right."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_881de53cf28d9a', 'les_99b46ef0609ea1', 'learn', 5, 'worked_example', '{"title":"Find the slope through $(-2, 5)$ and $(3, -5)$","steps":[{"latex":"m = \\frac{-5 - 5}{3 - (-2)}","explanation":"Subtracting a negative x-value adds."},{"latex":"m = \\frac{-10}{5} = -2","explanation":"A negative slope: the line falls from left to right."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4ca0cb0e75074c', 'les_99b46ef0609ea1', 'learn', 6, 'callout', '{"tone":"note","title":"Four kinds of slope","body":"Positive slope rises to the right; negative slope falls; a horizontal line has slope 0 because $\\Delta y = 0$; a vertical line has undefined slope because $\\Delta x = 0$ and we can''t divide by zero."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7a575b6fdf0418', 'les_99b46ef0609ea1', 'learn', 7, 'callout', '{"tone":"application","title":"Slope as a rate","body":"If a car''s distance goes from 30 miles at 1 hour to 150 miles at 3 hours, the slope is $\\frac{150 - 30}{3 - 1} = 60$ miles per hour. The units of slope are (units of $y$) per (unit of $x$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_055a1075c04af1', 'les_99b46ef0609ea1', 'experiment', 8, 'activity', '{"activity":"linear-graph","title":"Rise over run","params":{"m":2,"b":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8bd85fd628350e', 'les_99b46ef0609ea1', 'experiment', 9, 'callout', '{"tone":"tip","title":"Investigate","body":"Set $m = 0.5$, then $m = 2$, then $m = -2$. How does the triangle under the line change? What happens to the rise when the run is 1?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7180d1dfb3f681', 'les_99b46ef0609ea1', 'watch', 10, 'activity', '{"activity":"linear-graph","title":"Walkthrough: what slope looks like","steps":[{"title":"Slope 1","body":"With m = 1, every step right is one step up. The line makes a 45° angle with the axes.","params":{"m":1,"b":0}},{"title":"Steeper","body":"With m = 3, each step right rises 3. Larger slopes give steeper lines.","params":{"m":3,"b":0}},{"title":"Negative","body":"With m = −1.5, the line falls 1.5 for each step right.","params":{"m":-1.5,"b":0}},{"title":"Zero","body":"With m = 0 the line is horizontal: y never changes.","params":{"m":0,"b":2}}]}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c5a547ff4f539d', 'les_99b46ef0609ea1', 1, 'practice', 'numeric', 1, 'Find the slope of the line through $(2, 1)$ and $(6, 9)$.', '{"answer":2}', '["Rise: 9 − 1. Run: 6 − 2."]', '$m = \frac{9 - 1}{6 - 2} = \frac{8}{4} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4434e32cdcbdc2', 'les_99b46ef0609ea1', 2, 'practice', 'numeric', 2, 'Find the slope of the line through $(-3, 4)$ and $(1, -4)$.', '{"answer":-2}', '["$\\Delta x = 1 - (-3) = 4$."]', '$m = \frac{-4 - 4}{1 - (-3)} = \frac{-8}{4} = -2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_12196efeea09b8', 'les_99b46ef0609ea1', 3, 'practice', 'multiple_choice', 1, 'What is the slope of the line through $(5, 2)$ and $(5, 8)$?', '{"choices":["0","6","Undefined","1"],"answer":2}', '["What is the change in x?"]', '$\Delta x = 0$, so the line is vertical and its slope is undefined.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4184fc4a7bf6f0', 'les_99b46ef0609ea1', 4, 'practice', 'numeric', 2, 'A plant is 4 cm tall on day 2 and 13 cm tall on day 5. What is its average growth rate in cm per day?', '{"answer":3,"unit":"cm/day"}', '["Treat (day, height) as points."]', '$\frac{13 - 4}{5 - 2} = \frac{9}{3} = 3$ cm per day.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_881de53cf28d9a', 'les_99b46ef0609ea1', 5, 'review', 'numeric', 3, 'The line through $(1, k)$ and $(4, 11)$ has slope 3. Find $k$.', '{"answer":2}', '["Set up $\\frac{11 - k}{4 - 1} = 3$."]', '$11 - k = 9$, so $k = 2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_f64c7429d841d5', 'subj_math', 'slope', 'Slope', 'The ratio of vertical change to horizontal change between two points on a line.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_99b46ef0609ea1', (SELECT id FROM concepts WHERE slug = 'slope'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_99b46ef0609ea1', (SELECT id FROM formulas WHERE slug = 'slope'), 1);

-- Lesson: slope-intercept-form
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a917ef73842439', 'slope-intercept-form', 'Slope-intercept form', 'Write, read and graph lines in the form y = mx + b, and build linear models from a starting value and a rate.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6ef7fe742ea2be', 'les_a917ef73842439', 1, 'Identify the slope and y-intercept from y = mx + b.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7ad8b2fed08df9', 'les_a917ef73842439', 2, 'Graph a line from its slope-intercept equation.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9f8904a1e81aaf', 'les_a917ef73842439', 3, 'Write the equation of a line from a slope and a point, or from two points.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ef7fe742ea2be', 'les_a917ef73842439', 'learn', 1, 'formula', '{"latex":"y = mx + b","title":"Slope-intercept form","note":"$m$ is the slope and $b$ is the y-intercept, the y-value where the line crosses the y-axis (where $x = 0$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ad8b2fed08df9', 'les_a917ef73842439', 'learn', 2, 'text', '{"body":"This form tells a story: start at $b$ and change by $m$ for every unit of $x$. To graph $y = 2x - 3$, plot the intercept $(0, -3)$, then move right 1 and up 2 to $(1, -1)$, and draw the line through those points."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f8904a1e81aaf', 'les_a917ef73842439', 'learn', 3, 'worked_example', '{"title":"Write the equation of the line with slope $-\\tfrac{1}{2}$ through $(4, 1)$","steps":[{"latex":"1 = -\\tfrac{1}{2}(4) + b","explanation":"Substitute the slope and the point into y = mx + b."},{"latex":"1 = -2 + b","explanation":"Multiply."},{"latex":"b = 3","explanation":"Add 2 to both sides."},{"latex":"y = -\\tfrac{1}{2}x + 3","explanation":"Write the equation."}],"check":"At $x = 4$: $-2 + 3 = 1$. The point is on the line."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a21c123291f103', 'les_a917ef73842439', 'learn', 4, 'worked_example', '{"title":"Write the equation of the line through $(1, 5)$ and $(3, 11)$","steps":[{"latex":"m = \\frac{11 - 5}{3 - 1} = 3","explanation":"Find the slope first."},{"latex":"5 = 3(1) + b \\Rightarrow b = 2","explanation":"Use either point to find b."},{"latex":"y = 3x + 2","explanation":"Write the equation."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a2133280cc8351', 'les_a917ef73842439', 'learn', 5, 'callout', '{"tone":"application","title":"Linear models","body":"A pool holds 500 gallons and drains at 25 gallons per minute. The amount left is $V = -25t + 500$. The intercept 500 is the starting amount, the slope $-25$ is the rate, and setting $V = 0$ gives $t = 20$ minutes to empty."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c7e2b5e9d6029b', 'les_a917ef73842439', 'learn', 6, 'callout', '{"tone":"warning","title":"Read the form carefully","body":"In $y = 4 - 3x$, the slope is $-3$, not 4. Rewrite it as $y = -3x + 4$ to see $m$ and $b$ clearly."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8c1ae62e2072d0', 'les_a917ef73842439', 'experiment', 7, 'activity', '{"activity":"linear-graph","title":"Change m and b","params":{"m":-0.5,"b":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_089cb2fe8c038d', 'les_a917ef73842439', 'experiment', 8, 'callout', '{"tone":"tip","title":"Investigate","body":"Keep $m = 2$ and change $b$. What stays the same? Now keep $b = 1$ and change $m$. Which point never moves?"}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6ef7fe742ea2be', 'les_a917ef73842439', 1, 'practice', 'multiple_choice', 1, 'What are the slope and y-intercept of $y = 4 - 3x$?', '{"choices":["m = 4, b = −3","m = −3, b = 4","m = 3, b = 4","m = −3, b = −4"],"answer":1}', '["Rewrite as $y = -3x + 4$."]', '$y = -3x + 4$, so $m = -3$ and $b = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7ad8b2fed08df9', 'les_a917ef73842439', 2, 'practice', 'numeric', 1, 'The line $y = 2x - 7$ passes through $(5, y)$. Find $y$.', '{"answer":3}', '["Substitute x = 5."]', '$y = 2(5) - 7 = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9f8904a1e81aaf', 'les_a917ef73842439', 3, 'practice', 'short_text', 2, 'Write the equation of the line with slope 2 through $(3, 1)$, in the form y = mx + b.', '{"accept":["y=2x-5","y=-5+2x"]}', '["Substitute: $1 = 2(3) + b$."]', '$1 = 6 + b$, so $b = -5$ and $y = 2x - 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a21c123291f103', 'les_a917ef73842439', 4, 'practice', 'short_text', 2, 'Write the equation of the line through $(0, 4)$ and $(2, 0)$, in the form y = mx + b.', '{"accept":["y=-2x+4","y=4-2x"]}', '["(0, 4) is the y-intercept.","Slope = (0 − 4)/(2 − 0)."]', '$b = 4$ and $m = \frac{0 - 4}{2 - 0} = -2$, so $y = -2x + 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a2133280cc8351', 'les_a917ef73842439', 5, 'review', 'numeric', 3, 'A candle is 30 cm tall and burns 1.5 cm per hour. After how many hours is it 12 cm tall?', '{"answer":12,"unit":"h"}', '["Model: $h = -1.5t + 30$."]', '$12 = -1.5t + 30 \Rightarrow 1.5t = 18 \Rightarrow t = 12$ hours.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_9f867c79c5d637', 'subj_math', 'linear-functions', 'Linear functions', 'Functions with a constant rate of change, whose graphs are straight lines.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a917ef73842439', (SELECT id FROM concepts WHERE slug = 'linear-functions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a917ef73842439', (SELECT id FROM formulas WHERE slug = 'slope-intercept-form'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a917ef73842439', (SELECT id FROM formulas WHERE slug = 'point-slope-form'), 2);

-- Lesson: solving-two-step-equations
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bb511c6235b926', 'les_two_step_eq', 1, 'Use inverse operations and the properties of equality to isolate a variable.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5423a62f7bbc66', 'les_two_step_eq', 2, 'Undo operations in the reverse of the order they were applied.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e58754a29376ad', 'les_two_step_eq', 3, 'Check a solution by substituting it into the original equation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb511c6235b926', 'les_two_step_eq', 'experiment', 101, 'activity', '{"activity":"balance-equation","title":"Keep the equation balanced","params":{"a":3,"b":5,"c":20}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5423a62f7bbc66', 'les_two_step_eq', 'experiment', 102, 'callout', '{"tone":"tip","title":"Try this","body":"Set up $-4x + 6 = -10$. Which operation should come first? What happens if you divide by $-4$ first instead? Both orders can work, but one creates fractions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e58754a29376ad', 'les_two_step_eq', 'watch', 103, 'activity', '{"activity":"balance-equation","title":"Walkthrough: solving 3x + 5 = 20","steps":[{"title":"Start","body":"The equation 3x + 5 = 20 says both sides have the same value. Anything we do must be done to both sides.","params":{"a":3,"b":5,"c":20}},{"title":"Undo the addition","body":"Subtract 5 from both sides. The +5 disappears on the left and 20 becomes 15.","params":{"a":3,"b":0,"c":15}},{"title":"Undo the multiplication","body":"Divide both sides by 3. The left side is now x by itself and the right side is 5.","params":{"a":1,"b":0,"c":5}}]}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bb511c6235b926', 'les_two_step_eq', 1, 'practice', 'numeric', 1, 'Solve $2x + 7 = 19$.', '{"answer":6}', '["Subtract 7 from both sides first."]', '$2x = 12$, so $x = 6$. Check: $2(6) + 7 = 19$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5423a62f7bbc66', 'les_two_step_eq', 2, 'practice', 'numeric', 1, 'Solve $\frac{x}{5} - 3 = 4$.', '{"answer":35}', '["Add 3 to both sides, then multiply by 5."]', '$\frac{x}{5} = 7$, so $x = 35$. Check: $35 \div 5 - 3 = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e58754a29376ad', 'les_two_step_eq', 3, 'practice', 'numeric', 2, 'Solve $-4x + 6 = -10$.', '{"answer":4}', '["Subtract 6 from both sides.","Divide by $-4$; a negative divided by a negative is positive."]', '$-4x = -16$, so $x = 4$. Check: $-16 + 6 = -10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dcc26f33f7b224', 'les_two_step_eq', 4, 'practice', 'multiple_choice', 2, 'A student solved $3x - 9 = 12$ by first dividing both sides by 3 and got $x - 9 = 4$. What went wrong?', '{"choices":["Nothing; the next step gives x = 13.","Dividing by 3 must divide every term: x − 3 = 4.","You can never divide first.","They should have multiplied by 3."],"answer":1}', '["Division by 3 applies to the whole left side, 3x − 9."]', '$\frac{3x - 9}{3} = x - 3$, so the correct equation is $x - 3 = 4$ and $x = 7$. Dividing first works only if every term is divided.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6a184e77911da3', 'les_two_step_eq', 5, 'practice', 'numeric', 2, 'A gym charges a 30-dollar sign-up fee plus 15 dollars per month. Maya has paid 135 dollars in total. How many months has she been a member?', '{"answer":7}', '["Write $15m + 30 = 135$."]', '$15m = 105$, so $m = 7$ months.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_440bff955361de', 'les_two_step_eq', 6, 'review', 'short_text', 3, 'Solve $\frac{2x + 1}{3} = 5$. Enter your answer as x = …', '{"accept":["x=7","7"]}', '["Multiply both sides by 3 first.","Then 2x + 1 = 15."]', '$2x + 1 = 15$, $2x = 14$, $x = 7$. Check: $\frac{15}{3} = 5$.');

-- Lesson: unit-circle
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b4d0c21fb8eaab', 'unit-circle', 'The unit circle', 'Define sine and cosine for any angle using the unit circle, measure angles in radians, and find exact values for special angles.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_958d245f16ebc6', 'les_b4d0c21fb8eaab', 1, 'Convert between degrees and radians.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_175508dea6edc7', 'les_b4d0c21fb8eaab', 2, 'Define cos θ and sin θ as the coordinates of a point on the unit circle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ff685f5a2d1168', 'les_b4d0c21fb8eaab', 3, 'Find exact trigonometric values for multiples of π/6 and π/4, with correct signs in each quadrant.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_958d245f16ebc6', 'les_b4d0c21fb8eaab', 'learn', 1, 'definition', '{"term":"Unit circle","body":"The circle $x^2 + y^2 = 1$: radius 1, centered at the origin. Angles are measured from the positive x-axis, counterclockwise for positive angles."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_175508dea6edc7', 'les_b4d0c21fb8eaab', 'learn', 2, 'definition', '{"term":"Radian","body":"The measure of an angle that cuts off an arc of length 1 on the unit circle. A full turn is the circumference $2\\pi$, so $360° = 2\\pi$ radians and $180° = \\pi$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ff685f5a2d1168', 'les_b4d0c21fb8eaab', 'learn', 3, 'formula', '{"latex":"\\text{radians} = \\text{degrees} \\times \\frac{\\pi}{180}","title":"Converting angles"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_05895ddea1c520', 'les_b4d0c21fb8eaab', 'learn', 4, 'text', '{"body":"For any angle $\\theta$, the terminal side meets the unit circle at one point. Its coordinates define the two basic trigonometric functions: $\\cos\\theta$ is the x-coordinate and $\\sin\\theta$ is the y-coordinate. This works for every angle, not just acute angles in right triangles, and it agrees with SOH CAH TOA because the hypotenuse here is 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cbc284ea0134f4', 'les_b4d0c21fb8eaab', 'learn', 5, 'formula', '{"latex":"(\\cos\\theta,\\ \\sin\\theta), \\qquad \\tan\\theta = \\frac{\\sin\\theta}{\\cos\\theta}","title":"Point on the unit circle","note":"$\\tan\\theta$ is undefined when $\\cos\\theta = 0$, at $\\theta = \\frac{\\pi}{2} + k\\pi$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d21ec9104af4f0', 'les_b4d0c21fb8eaab', 'learn', 6, 'worked_example', '{"title":"Find exact values at $\\theta = \\frac{\\pi}{6}$ (30°)","steps":[{"latex":"\\text{30-60-90 triangle with hypotenuse } 1","explanation":"Drop a perpendicular from the point to the x-axis."},{"latex":"\\text{short leg} = \\tfrac{1}{2},\\ \\text{long leg} = \\tfrac{\\sqrt{3}}{2}","explanation":"The short leg is opposite the 30° angle."},{"latex":"\\cos\\tfrac{\\pi}{6} = \\tfrac{\\sqrt{3}}{2},\\quad \\sin\\tfrac{\\pi}{6} = \\tfrac{1}{2}","explanation":"x is the horizontal leg, y the vertical leg."}],"check":"$\\left(\\tfrac{\\sqrt{3}}{2}\\right)^2 + \\left(\\tfrac{1}{2}\\right)^2 = \\tfrac{3}{4} + \\tfrac{1}{4} = 1$, so the point is on the unit circle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1c9e2ca8d7278a', 'les_b4d0c21fb8eaab', 'learn', 7, 'worked_example', '{"title":"Find $\\sin\\frac{5\\pi}{4}$ and $\\cos\\frac{5\\pi}{4}$","steps":[{"latex":"\\tfrac{5\\pi}{4} = \\pi + \\tfrac{\\pi}{4}","explanation":"The angle is in Quadrant III, 45° past the negative x-axis."},{"latex":"\\text{reference angle } \\tfrac{\\pi}{4}:\\ \\tfrac{\\sqrt{2}}{2},\\ \\tfrac{\\sqrt{2}}{2}","explanation":"Same size coordinates as 45°."},{"latex":"\\cos\\tfrac{5\\pi}{4} = -\\tfrac{\\sqrt{2}}{2},\\quad \\sin\\tfrac{5\\pi}{4} = -\\tfrac{\\sqrt{2}}{2}","explanation":"In Quadrant III both x and y are negative."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fb9e16ec1b238f', 'les_b4d0c21fb8eaab', 'learn', 8, 'callout', '{"tone":"tip","title":"Signs by quadrant","body":"Quadrant I: all positive. II: sine positive. III: tangent positive. IV: cosine positive. Every other value in that quadrant is negative."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8a806fefaea5be', 'les_b4d0c21fb8eaab', 'learn', 9, 'callout', '{"tone":"application","title":"Where this shows up","body":"Anything that goes around in circles traces sine and cosine: the height of a seat on a Ferris wheel, alternating current, sound waves, and the position of a planet in a circular orbit."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9bd527147103ea', 'les_b4d0c21fb8eaab', 'experiment', 10, 'activity', '{"activity":"unit-circle","title":"Rotate the angle","params":{"degrees":true}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8093b4e53d5d04', 'les_b4d0c21fb8eaab', 'experiment', 11, 'callout', '{"tone":"tip","title":"Investigate","body":"Find two angles between 0 and $2\\pi$ where $\\sin\\theta = \\tfrac{1}{2}$. Why are there two? Where is $\\tan\\theta$ undefined, and what happens to the tangent segment as you approach it?"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fed4ba84504c05', 'les_b4d0c21fb8eaab', 'watch', 12, 'activity', '{"activity":"unit-circle","title":"Walkthrough: sine and cosine as coordinates","steps":[{"title":"Start at 0","body":"At 0 rad the point is (1, 0): cos 0 = 1 and sin 0 = 0.","params":{"angle":0}},{"title":"30°","body":"At π/6 the point is (√3/2, 1/2).","params":{"angle":30}},{"title":"Straight up","body":"At π/2 the point is (0, 1): cosine is 0 and sine is 1; tangent is undefined.","params":{"angle":90}},{"title":"Quadrant II","body":"At 2π/3 the x-coordinate is negative: cos = −1/2, sin = √3/2.","params":{"angle":120}},{"title":"Quadrant III","body":"At 5π/4 both coordinates are negative: (−√2/2, −√2/2).","params":{"angle":225}}]}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_958d245f16ebc6', 'les_b4d0c21fb8eaab', 1, 'practice', 'numeric', 1, 'Convert 135° to radians. Give a decimal to 3 places.', '{"answer":2.356,"tolerance":0.001}', '["Multiply by $\\frac{\\pi}{180}$."]', '$135 \cdot \frac{\pi}{180} = \frac{3\pi}{4} \approx 2.356$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_175508dea6edc7', 'les_b4d0c21fb8eaab', 2, 'practice', 'numeric', 1, 'Convert $\frac{5\pi}{6}$ radians to degrees.', '{"answer":150,"unit":"°"}', '["Multiply by $\\frac{180}{\\pi}$."]', '$\frac{5\pi}{6} \cdot \frac{180}{\pi} = 150°$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ff685f5a2d1168', 'les_b4d0c21fb8eaab', 3, 'practice', 'multiple_choice', 2, 'What is $\cos\frac{2\pi}{3}$?', '{"choices":["$\\tfrac{1}{2}$","$-\\tfrac{1}{2}$","$\\tfrac{\\sqrt{3}}{2}$","$-\\tfrac{\\sqrt{3}}{2}$"],"answer":1}', '["$\\frac{2\\pi}{3}$ is 120°, in Quadrant II, with reference angle 60°."]', '$\cos 60° = \tfrac{1}{2}$ and cosine is negative in Quadrant II, so $\cos\frac{2\pi}{3} = -\tfrac{1}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_05895ddea1c520', 'les_b4d0c21fb8eaab', 4, 'practice', 'numeric', 2, 'Find $\sin\frac{7\pi}{6}$.', '{"answer":-0.5,"tolerance":0.0001}', '["$\\frac{7\\pi}{6} = \\pi + \\frac{\\pi}{6}$: Quadrant III."]', 'Reference angle $\frac{\pi}{6}$ gives $\tfrac{1}{2}$; sine is negative in Quadrant III, so $-\tfrac{1}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cbc284ea0134f4', 'les_b4d0c21fb8eaab', 5, 'practice', 'multiple_choice', 2, 'For which angle is $\tan\theta$ undefined?', '{"choices":["$0$","$\\frac{\\pi}{4}$","$\\frac{3\\pi}{2}$","$\\pi$"],"answer":2}', '["Where is $\\cos\\theta = 0$?"]', 'At $\frac{3\pi}{2}$ the point is $(0, -1)$, so $\tan = \frac{-1}{0}$ is undefined.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d21ec9104af4f0', 'les_b4d0c21fb8eaab', 6, 'review', 'numeric', 3, 'If $\sin\theta = \tfrac{3}{5}$ and $\theta$ is in Quadrant II, find $\cos\theta$.', '{"answer":-0.8,"tolerance":0.0001}', '["Use $\\sin^2\\theta + \\cos^2\\theta = 1$.","Cosine is negative in Quadrant II."]', '$\cos^2\theta = 1 - \tfrac{9}{25} = \tfrac{16}{25}$, so $\cos\theta = -\tfrac{4}{5} = -0.8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1c9e2ca8d7278a', 'les_b4d0c21fb8eaab', 7, 'review', 'short_text', 3, 'Find all $\theta$ in $[0, 2\pi)$ with $\cos\theta = \frac{\sqrt{2}}{2}$. Enter them in degrees, separated by a comma, smallest first.', '{"accept":["45,315","45°,315°"]}', '["Cosine is positive in Quadrants I and IV."]', 'Reference angle 45°: $\theta = 45°$ and $\theta = 360° - 45° = 315°$, i.e. $\frac{\pi}{4}$ and $\frac{7\pi}{4}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_b4d0c21fb8eaab', 'subj_math', 'unit-circle', 'Unit circle', 'The circle of radius 1 centered at the origin, used to define trigonometric functions for all angles.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b4d0c21fb8eaab', (SELECT id FROM concepts WHERE slug = 'unit-circle'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a6aedb62ecc78a', 'subj_math', 'radian-measure', 'Radian measure', 'Angle measure equal to arc length on a circle of radius 1.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b4d0c21fb8eaab', (SELECT id FROM concepts WHERE slug = 'radian-measure'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b4d0c21fb8eaab', (SELECT id FROM formulas WHERE slug = 'pythagorean-identity'), 1);

-- Lesson: variables-and-expressions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_96c294794ed377', 'variables-and-expressions', 'Variables and algebraic expressions', 'Use letters to stand for numbers, translate words into expressions, and evaluate expressions for given values.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d2a9b8e15d8a0', 'les_96c294794ed377', 1, 'Identify variables, coefficients, constants and terms in an expression.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ab56c70c5d7682', 'les_96c294794ed377', 2, 'Translate verbal descriptions into algebraic expressions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9643c63e25861d', 'les_96c294794ed377', 3, 'Evaluate an expression by substituting values and following the order of operations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d2a9b8e15d8a0', 'les_96c294794ed377', 'learn', 1, 'text', '{"body":"A variable is a letter that stands for a number we don''t know yet, or a number that can change. Instead of writing \"some number plus five\", algebra writes $n + 5$. That short line can describe every possible case at once: if $n$ is 2 the value is 7, if $n$ is 10 the value is 15."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ab56c70c5d7682', 'les_96c294794ed377', 'learn', 2, 'definition', '{"term":"Algebraic expression","body":"A combination of numbers, variables and operations, such as $3x + 7$ or $\\frac{a}{2} - b$. An expression has a value but no equals sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9643c63e25861d', 'les_96c294794ed377', 'learn', 3, 'text', '{"body":"Expressions are built from terms, which are separated by $+$ and $-$ signs. In $4x^2 - 3x + 9$ there are three terms. The number multiplying a variable is its coefficient: the coefficient of $x^2$ is 4 and the coefficient of $x$ is $-3$. A term with no variable, like 9, is a constant."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87fcece66a3212', 'les_96c294794ed377', 'learn', 4, 'callout', '{"tone":"tip","title":"Key phrases","body":"\"More than\" and \"increased by\" mean add. \"Less than\" reverses the order: \"5 less than $x$\" is $x - 5$, not $5 - x$. \"Product\" means multiply and \"quotient\" means divide."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_126552c261a69f', 'les_96c294794ed377', 'learn', 5, 'worked_example', '{"title":"Write \"three times a number, decreased by 4\" as an expression","steps":[{"latex":"n","explanation":"Let n stand for the unknown number."},{"latex":"3n","explanation":"Three times the number."},{"latex":"3n - 4","explanation":"Decreased by 4 means subtract 4 from that product."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d0d0fef679ecc', 'les_96c294794ed377', 'learn', 6, 'worked_example', '{"title":"Evaluate $2a^2 - 3b$ when $a = -3$ and $b = 4$","steps":[{"latex":"2(-3)^2 - 3(4)","explanation":"Substitute, keeping each value in parentheses so signs aren''t lost."},{"latex":"2(9) - 12","explanation":"Exponents first: (−3)² = 9. Then multiply 3 · 4."},{"latex":"18 - 12 = 6","explanation":"Multiply, then subtract."}],"check":"Writing $-3^2$ without parentheses would give $-9$, a common error. The square applies to $-3$ as a whole because we substituted it in parentheses."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_56deafae2ab1d2', 'les_96c294794ed377', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"A phone plan charges 25 dollars a month plus 2 dollars per gigabyte. The monthly cost is $25 + 2g$ for $g$ gigabytes. Evaluating at $g = 8$ gives $25 + 16 = 41$ dollars."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_db2499b439f4c7', 'les_96c294794ed377', 'learn', 8, 'callout', '{"tone":"note","title":"Coming next","body":"Once two expressions are set equal to each other, you have an equation. Solving equations is the next step and builds directly on evaluating expressions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d2a9b8e15d8a0', 'les_96c294794ed377', 1, 'practice', 'multiple_choice', 1, 'Which expression means "7 less than a number $x$"?', '{"choices":["$7 - x$","$x - 7$","$7x$","$x + 7$"],"answer":1}', '["\"Less than\" reverses the order in which the words appear."]', 'Start with $x$ and take 7 away: $x - 7$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ab56c70c5d7682', 'les_96c294794ed377', 2, 'practice', 'numeric', 1, 'Evaluate $5x + 3$ when $x = 4$.', '{"answer":23}', '["Replace x with 4, then multiply before adding."]', '$5(4) + 3 = 20 + 3 = 23$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9643c63e25861d', 'les_96c294794ed377', 3, 'practice', 'numeric', 2, 'Evaluate $3a^2 - 2b$ when $a = -2$ and $b = 5$.', '{"answer":2}', '["Square $-2$ first: $(-2)^2 = 4$.","Then 3 · 4 = 12 and 2 · 5 = 10."]', '$3(-2)^2 - 2(5) = 3(4) - 10 = 12 - 10 = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87fcece66a3212', 'les_96c294794ed377', 4, 'practice', 'multiple_choice', 2, 'What is the coefficient of $x$ in $6x^2 - x + 11$?', '{"choices":["6","1","−1","11"],"answer":2}', '["The term with $x$ (not $x^2$) is $-x$."]', '$-x$ means $-1 \cdot x$, so the coefficient is $-1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_126552c261a69f', 'les_96c294794ed377', 5, 'practice', 'short_text', 2, 'A taxi charges a 4-dollar base fare plus 3 dollars per mile. Write an expression for the cost of $m$ miles, using $m$.', '{"accept":["4+3m","3m+4","4+3*m","3*m+4"]}', '["What is charged once, and what is charged for each mile?"]', 'The 4 dollars is charged once and 3 dollars for each of the $m$ miles: $3m + 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5d0d0fef679ecc', 'les_96c294794ed377', 6, 'review', 'numeric', 3, 'Evaluate $\frac{x^2 - 4}{x + 2}$ when $x = 6$.', '{"answer":4}', '["Compute the top and bottom separately before dividing."]', 'Top: $36 - 4 = 32$. Bottom: $6 + 2 = 8$. $32 \div 8 = 4$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_a508e15939726d', 'subj_math', 'algebraic-expressions', 'Algebraic expressions', 'Combinations of numbers, variables and operations that represent a quantity.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_96c294794ed377', (SELECT id FROM concepts WHERE slug = 'algebraic-expressions'));

